'use strict';
const $ = (selector, root=document) => root.querySelector(selector);
const escape = value => String(value ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state = {session:null, studies:[], study:null, view:'overview', route:0};
const sections=[['overview','Overview'],['documentation','Living documentation'],['document','Document library'],['discussion','Discussions'],['task','Tasks & decisions'],['idea','Ideas & whiteboards'],['handoff','Handoff snapshots'],['activity','Activity & lifecycle']];
const titles={documentation:'Living documentation',document:'Document library',discussion:'Discussions',task:'Tasks & decisions',idea:'Ideas & whiteboards'};
const liveFiles=()=> (state.study?.files||[]).filter(f=>!f.deleted);
const date=value=>value?new Date(value).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}):'Date unavailable';
const items=(kind)=> (state.study?.items||[]).filter(i=>!i.deleted&&(!kind||i.kind===kind));
const badge=stage=>`<span class="pill ${escape(String(stage).toLowerCase())}">${escape(stage)}</span>`;
function notice(message,error=false){const node=$('#notice');node.textContent=message;node.hidden=!message;node.className=`notice${error?' error':''}`;if(error)node.scrollIntoView({block:'nearest'});}
async function api(path, data){const response=await fetch(path,{method:data?'POST':'GET',credentials:'same-origin',headers:data?{'Content-Type':'application/json','X-CSRF-TOKEN':state.session?.csrf||''}:{},body:data?JSON.stringify(data):undefined});let body;try{body=await response.json();}catch{body={};}if(!response.ok)throw new Error(body.message||body.error||body.title||`Request could not be completed (${response.status}).`);return body;}
async function refreshSession(){state.session=await api('/api/session');const identities=state.session.identities||[];$('#identity').innerHTML=identities.map(i=>`<option value="${escape(i.id)}" ${i.id===state.session.user.id?'selected':''}>${escape(i.name)}</option>`).join('');$('#admin-nav').hidden=state.session.user.role!=='Administrator';document.querySelectorAll('[data-js-control]').forEach(control=>control.hidden=false);}
async function route(){const ticket=++state.route;notice('');const parts=location.hash.slice(1).split('/');state.study=null;$('#main').setAttribute('aria-busy','true');try{if(parts[0]==='admin'){const admin=await api('/api/admin');if(ticket!==state.route)return;renderAdmin(admin);}else if(parts[0]==='study'&&parts[1]){const study=await api(`/api/studies/${encodeURIComponent(parts[1])}`);if(ticket!==state.route)return;state.study=study;[state.protocolAvailability,state.documentWorkspace,state.decisionWorkspace]=await Promise.all([api(`/api/studies/${encodeURIComponent(study.id)}/protocol`),api(`/api/studies/${encodeURIComponent(study.id)}/documents`),api(`/api/studies/${encodeURIComponent(study.id)}/decisions`)]);if(ticket!==state.route)return;state.view=sections.some(s=>s[0]===parts[2])?parts[2]:'overview';renderStudy();if(state.view==='overview')loadOnboarding();if(state.view==='documentation')loadDocumentationResources();if(state.view==='idea')loadBoards(parts[3]?.startsWith('board-')?decodeURIComponent(parts[3].slice(6)):null,parts[4]?decodeURIComponent(parts[4]):null);if(state.view==='handoff')loadHandoffs();if(parts[3]){const target=document.getElementById('record-'+decodeURIComponent(parts[3]));if(target){for(let parent=target.parentElement;parent;parent=parent.parentElement)if(parent.tagName==='DETAILS')parent.open=true;target.tabIndex=-1;target.scrollIntoView({block:'center'});target.focus();}}if(state.view==='activity'&&state.session.user.role==='Administrator')loadImportReports();}else{const studies=await api('/api/studies');if(ticket!==state.route)return;state.studies=studies;renderStudies();}$('#studies-nav').setAttribute('aria-current',parts[0]==='admin'?'false':'page');$('#admin-nav').setAttribute('aria-current',parts[0]==='admin'?'page':'false');}catch(error){if(ticket!==state.route)return;$('#main').innerHTML=`<div class="panel empty"><h1>Workspace unavailable</h1><p>${escape(error.message)}</p><a href="#studies">Return to My studies</a></div>`;}finally{if(ticket===state.route)$('#main').removeAttribute('aria-busy');}}
function renderStudies(){const studies=state.studies;$('#main').innerHTML=`<div class="page-heading"><div><p class="eyebrow">Your research workspace</p><h1>My studies</h1><p class="muted">Shared context. Clear next steps. A lasting record of your team's work.</p></div><span class="count-badge">${studies.length} accessible ${studies.length===1?'study':'studies'}</span></div><div class="study-grid">${studies.map((s,n)=>`<article class="study-card"><div class="card-top">${badge(s.stage)}<span class="muted">STUDY ${String(n+1).padStart(2,'0')}</span></div><h2><a href="#study/${encodeURIComponent(s.id)}/overview">${escape(s.title)}</a></h2><p>${escape(s.summary)}</p><div class="card-bottom"><span class="muted">Group-based access</span><a href="#study/${encodeURIComponent(s.id)}/overview">Open workspace <span aria-hidden="true">→</span></a></div></article>`).join('')||'<div class="panel empty wide"><h2>No study access</h2><p>This identity has no mapped study-group membership. Administrative roles do not grant study content access.</p></div>'}</div><section class="welcome-strip"><span class="welcome-icon" aria-hidden="true">↗</span><div><h2>Pick up where the work left off</h2><p>Each workspace brings together the current plan, versioned documents, conversations, and decisions. Use the demo identity selector to explore how group access changes.</p></div></section><div class="overview-grid integrations-grid"><div class="integration"><strong>Study assistant · Disabled</strong>No AI requests or generated research conclusions. Core study work is available independently.</div><div class="integration"><strong>Teams connection · Disabled</strong>No messages are sent or synchronized. The study record stays in this local application.</div></div>`;}
function renderStudy(){const s=state.study;document.title=`${s.title} · Research Collaboration Hub`;$('#main').innerHTML=`<div class="breadcrumb"><a href="#studies">My studies</a> <span aria-hidden="true"> / </span> Study workspace</div><div class="page-heading"><div><p class="eyebrow">Study workspace</p><h1>${escape(s.title)}</h1><p class="muted">${escape(s.summary)}</p></div>${badge(s.stage)}</div><div class="study-shell"><nav class="study-nav" aria-label="Study sections"><p>Workspace</p>${sections.map(([id,label])=>`<a href="#study/${encodeURIComponent(s.id)}/${id}" ${id===state.view?'aria-current="page"':''}>${label}</a>`).join('')}</nav><div id="study-content">${state.view==='overview'?overview():state.view==='activity'?activity():state.view==='handoff'?handoffWorkspace():state.view==='idea'?brainstormWorkspace():state.view==='task'?workPlan():collection()}</div></div>`;}
function linkView(view,label){return `<a class="small-link" href="#study/${encodeURIComponent(state.study.id)}/${view}">${label} <span aria-hidden="true">→</span></a>`;}
function overview(){const docs=items('document').sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));const questions=items('discussion');const tasks=items('task').filter(i=>i.task?.status!=='Done');const decisions=(state.decisionWorkspace?.current||[]).map(entry=>entry.item);return `<div id="onboarding-panel" aria-live="polite"></div><div class="content-heading"><h2>At a glance</h2><span class="screen-note">Workspace revision ${state.study.revision}</span></div><div class="overview-grid">${protocolPanel()}<section class="panel"><p class="label">People & access</p><h3>${state.study.id==='atlas'?'Riley · synthetic study lead':'Sam · synthetic study contact'}</h3><p class="screen-note">Study contact for this demonstration. Contact details are synthetic.</p><strong>${escape(state.session.user.name)}</strong><p class="muted">Signed in as a synthetic study participant.</p><p class="screen-note">Membership is derived from the mapped demo directory group. Assignment or an application role does not grant membership.</p></section><section class="panel"><div class="row-head"><h2>Open conversations</h2>${linkView('discussion','View all')}</div>${questions.slice(0,3).map(i=>`<div class="recent-item"><a href="${recordRoute(state.study.id,i)}">${escape(i.title)}</a><div class="muted">${escape(i.author)} · ${date(i.createdAt)}</div></div>`).join('')||'<p class="muted">No questions yet. Start a discussion around the current plan.</p>'}</section><section class="panel"><div class="row-head"><h2>Next actions</h2>${linkView('task','View plan')}</div>${tasks.slice(0,3).map(i=>`<div class="recent-item"><a href="${recordRoute(state.study.id,i)}">${escape(i.title)}</a><div class="muted">${escape(i.body.slice(0,100))}</div><div class="overview-task-meta"><span class="pill">${escape(i.task?.status||'Open')}</span><span>Owner: ${escape(identityName(i.task?.assignee)||'Unassigned')}</span><span>Due: ${escape(i.task?.dueDate||'Not set')}</span></div></div>`).join('')||'<p class="muted">Capture the next step with its owner and supporting context.</p>'}</section><section class="panel wide"><h2>Start here</h2><ol class="onboarding-steps"><li>${linkView('documentation','Read the study orientation')}</li><li>${linkView('document','Review the current document family and review state')}</li><li>${linkView('discussion','Follow the open questions and their evidence')}</li><li>${linkView('task','Confirm the next action and its owner')}</li><li>${linkView('handoff','Review a fixed handoff snapshot')}</li></ol></section><section class="panel wide"><div class="row-head"><h2>Recent decisions</h2>${linkView('task','Decision trail')}</div>${decisions.slice(-2).reverse().map(i=>record(i,false)).join('')||'<p class="muted">Decisions will appear here with their rationale and evidence.</p>'}</section></div>`;}
function collection(){const view=state.view;const descriptions={documentation:'Living notes and onboarding context. These notes retain earlier entries; the document library provides governed Draft, Review, and Accepted versions.',document:'Every revision retains its author and context. Text documents and synthetic file attachments are available in this preview.',discussion:'Ask a question, follow the replies, and link the exact evidence that informed the conversation.',task:'Keep next actions and decisions together with their rationale and supporting records.',idea:'An accessible, keyboard-friendly list for brainstorming. Each idea is retained as a study record.'};const labels={documentation:'Add documentation',document:'Add document',discussion:'Start discussion',task:'Add task',idea:'Capture idea'};let records=items(view);if(view==='task')records=items().filter(i=>['task','decision'].includes(i.kind));return `<div class="content-heading"><h2>${titles[view]}</h2><button class="usa-button" data-action="new" data-kind="${view}">${labels[view]}</button></div><p class="section-description">${descriptions[view]}</p><div id="editor"></div>${view==='documentation'?'<div id="documentation-tools">Loading templates and resource pointers…</div>':''}${view==='document'?`<section class="panel"><div class="row-head"><h3>Uploaded files</h3><button class="text-button" data-action="upload">Upload file</button></div><p class="screen-note">Synthetic files only · 512 KiB maximum. File release uses a demo policy, not a malware scanner.</p>${fileFamilies()||'<p class="muted">No uploaded files yet.</p>'}</section>`:''}${view==='task'?'<p><button class="text-button" data-action="new" data-kind="decision">+ Record a decision</button></p>':''}${view==='idea'?`<ol class="idea-list">${records.map(i=>`<li><div>${record(i)}</div></li>`).join('')}</ol>${records.length?'':'<div class="panel empty"><h3>Make room for the next idea</h3><p>Capture a proposal, alternatives, or a question for the team.</p></div>'}`:`<section class="panel" aria-label="${titles[view]}">${(view==='document'?documentFamilies():records.map(i=>record(i)).join(''))||'<div class="empty"><h3>A shared record starts here</h3><p>Add the first item to this part of the workspace.</p></div>'}</section>`}`;}
function record(i,actions=true){const replies=items('reply').filter(r=>r.parentId===i.id);const evidence=i.parentId?items().find(r=>r.id===i.parentId):null;return `<article class="record" id="record-${escape(i.id)}"><div class="record-meta"><span>${escape(i.kind)}</span>${i.version?`<span>Version ${escape(i.version)}</span>`:''}<span>${escape(i.author)}</span><span>${date(i.createdAt)}</span></div><h3>${escape(i.title)}</h3>${i.kind==='document'?documentReviewSummary(i):''}${renderRecordBody(i)}${i.kind==='task'?taskMetadata(i):''}${i.kind==='decision'?decisionMetadata(i):''}${provenanceDetails(i)}${i.template?`<p class="screen-note">Created from template: ${escape(i.template.title)}${i.template.version?' · Definition version '+escape(i.template.version):''} · The saved Draft is independent of later template changes.</p>`:''}${boardRecordProvenance(i)}${i.documentId?`<div class="screen-note">Document evidence: ${itemEvidence(i.documentId)}</div>`:''}${fileEvidence(i.fileIds||[])}${evidence?`<p class="screen-note">Linked evidence: ${escape(evidence.title)}${evidence.version?` · version ${escape(evidence.version)}`:''}</p>`:''}${actions?`<div class="record-actions">${['discussion','reply'].includes(i.kind)?`<button class="text-button" data-action="attach" data-id="${escape(i.id)}">Attach file</button>`:''}${i.kind==='task'?`<button class="text-button" data-action="edit-task" data-id="${escape(i.id)}">Update task</button>`:''}${['discussion','reply'].includes(i.kind)?`<button class="text-button" data-action="reply" data-id="${escape(i.id)}">Reply</button><button class="text-button" data-action="decision" data-id="${escape(i.id)}">Record decision</button>`:''}${i.kind==='document'?documentStateActions(i):''}${i.kind==='decision'?decisionActions(i):''}${['document','documentation'].includes(i.kind)?`<button class="text-button" data-action="revise" data-id="${escape(i.id)}">Add revision</button>${i.kind==='document'?`<a class="small-link" href="/api/studies/${encodeURIComponent(state.study.id)}/documents/${encodeURIComponent(i.id)}/download">Download text</a>`:''}`:''}${i.kind==='idea'?`<button class="text-button" data-action="decision" data-id="${escape(i.id)}">Turn into decision</button>`:''}</div>`:''}${liveFiles().filter(f=>f.parentId===i.id).map(fileRecord).join('')}${replies.map(r=>`<div class="reply">${record(r,actions)}</div>`).join('')}</article>`;}
function activity(){const s=state.study;return `${protocolPanel(true)}${importPanel()}<div class="content-heading"><h2>Activity & lifecycle</h2></div><section class="panel"><h3>Study status</h3><p class="muted">This is a workspace status, not external study approval. Closed studies keep their record and can be reopened.</p><form id="stage-form" class="stage-form"><label for="stage">Workspace stage</label><select id="stage" name="stage" class="usa-select">${['Active','Paused','Closed'].map(stage=>`<option ${stage.toLowerCase()===s.stage.toLowerCase()?'selected':''}>${stage}</option>`).join('')}</select><button class="usa-button" type="submit">Update stage</button></form></section><section class="panel"><h3>Record history</h3>${items().slice().reverse().map(i=>`<div class="recent-item"><strong>${escape(i.title)}</strong><div class="muted">${escape(i.kind)} · ${escape(i.author)} · ${date(i.createdAt)}${i.version?' · version '+escape(i.version):''}</div></div>`).join('')}</section>`;}
function showEditor(kind,source=null,revision=false){if(kind==='decision'){showDecisionEditor(source);return;}if(kind==='task'){showTaskEditor(source);return;}if(kind==='document'){showDocumentEditor(source,revision);return;}const target=$('#editor');if(!target)return;const evidence=source&&!revision?source.id:'';const requestId=crypto.randomUUID();target.innerHTML=`<section class="form-panel"><h3>${revision?'Add a new revision':kind==='reply'?'Reply to discussion':'Add '+kind}</h3><form id="item-form" data-kind="${escape(kind)}" data-request="${requestId}" data-parent="${escape(evidence)}" data-document="${revision?escape(source.kind==='document'?source.id:source.documentId||''):''}"><label for="item-title" class="usa-label">${kind==='reply'?'Reply subject':'Title'}</label><input id="item-title" name="title" class="usa-input" required maxlength="160" value="${escape(revision?source.title:kind==='reply'?'Re: '+source.title:'')}"><label for="item-body" class="usa-label">${kind==='decision'?'Decision, rationale, and alternatives':kind==='task'?'Owner, next action, and evidence':'Content'}</label><textarea id="item-body" name="body" class="usa-textarea" required maxlength="20000">${escape(revision?source.body:'')}</textarea><p class="form-hint">Synthetic demonstration content only. Saved records retain author and time.</p>${!source&&['discussion','decision','task'].includes(kind)?`<label for="evidence" class="usa-label">Link exact document version (optional)</label><select class="usa-select" id="evidence" name="documentId"><option value="">No linked document</option>${items().filter(i=>i.kind==='document').map(i=>`<option value="${escape(i.id)}">${escape(i.title)}${i.version?' — v'+escape(i.version):''}</option>`).join('')}</select>`:''}${fileEvidencePicker('fileIds',revision?source.fileIds||[]:[])}${evidence?`<p class="form-hint">Linked to: ${escape(source.title)}</p>`:''}<div class="form-row"><button class="usa-button" type="submit">Save ${kind==='reply'?'reply':'record'}</button><button class="text-button" type="button" data-action="cancel">Cancel</button></div><p id="form-error" class="form-hint" role="alert"></p></form></section>`;$('#item-title').focus();}
function renderAdmin(data){state.configRevision=data.configRevision;const identities=(data.identities||[]).map(i=>({...i,role:data.roles?.[i.id]||'Researcher',groups:data.groups?.[i.id]||[],accessible:(data.effectiveAccess||[]).find(a=>a.identity===i.id)?.studies||[]}));const mappings=Array.isArray(data.mappings)?data.mappings:Object.entries(data.mappings||{}).map(([studyId,groupId])=>({studyId,groupId}));$('#main').innerHTML=`<div class="page-heading"><div><p class="eyebrow">Service administration</p><h1>Access & configuration</h1><p class="muted">Manage application responsibilities and study group mappings. Directory membership remains authoritative.</p></div><span class="count-badge">Synthetic directory</span></div><div class="overview-grid"><section class="panel"><h2>Application roles</h2><p class="screen-note">An administrator can manage configuration without gaining study content access.</p><form id="role-form" data-revision="${data.configRevision}" data-request="${crypto.randomUUID()}"><label class="usa-label" for="role-identity">Synthetic identity</label><select id="role-identity" name="identity" class="usa-select">${identities.map(i=>`<option value="${escape(i.id)}">${escape(i.name)} (${escape(i.role)})</option>`).join('')}</select><label class="usa-label" for="role">Application role</label><select id="role" name="role" class="usa-select"><option>Researcher</option><option>Administrator</option></select><div class="form-row"><button class="usa-button" type="submit">Save role</button></div></form></section><section class="panel"><h2>Study group mapping</h2><p class="screen-note">Map a study to an existing synthetic group. This does not edit directory membership.</p><form id="mapping-form" data-revision="${data.configRevision}" data-request="${crypto.randomUUID()}"><label class="usa-label" for="mapping-study">Study</label><select id="mapping-study" name="studyId" class="usa-select">${mappings.map(m=>`<option value="${escape(m.studyId||m.id)}">${escape(m.title||m.studyId||m.id)}</option>`).join('')}</select><label class="usa-label" for="mapping-group">Stable group identifier</label><input id="mapping-group" name="groupId" class="usa-input" required maxlength="100" value="${escape(mappings[0]?.groupId||'')}"><div class="form-row"><button class="usa-button" type="submit">Save mapping</button></div></form></section><section class="panel wide"><h2>Effective access inputs</h2><p class="screen-note">Synthetic identity group claims and current mappings determine access. No separately maintained study roster.</p><div class="table-wrap" role="region" aria-label="Scrollable administration table" tabindex="0"><table class="usa-table"><caption class="usa-sr-only">Synthetic identity roles and groups</caption><thead><tr><th scope="col">Identity</th><th scope="col">Application role</th><th scope="col">Directory groups</th><th scope="col">Effective study access</th></tr></thead><tbody>${identities.map(i=>`<tr><th scope="row">${escape(i.name)}</th><td>${escape(i.role)}</td><td>${escape((i.groups||i.groupIds||[]).join(', ')||'No study groups')}</td><td>${escape(i.accessible.join(', ')||'No study access')}</td></tr>`).join('')}</tbody></table></div><div class="table-wrap" role="region" aria-label="Scrollable administration table" tabindex="0"><table class="usa-table"><caption class="usa-sr-only">Study to directory group mappings</caption><thead><tr><th scope="col">Study</th><th scope="col">Authoritative group</th></tr></thead><tbody>${mappings.map(m=>`<tr><th scope="row">${escape(m.title||m.studyId||m.id)}</th><td><code>${escape(m.groupId)}</code></td></tr>`).join('')}</tbody></table></div></section><section class="panel wide"><h2>Administrative audit</h2><div class="table-wrap" role="region" aria-label="Scrollable administration table" tabindex="0"><table class="usa-table"><caption class="usa-sr-only">Recent audited actions</caption><thead><tr><th scope="col">When</th><th scope="col">Actor</th><th scope="col">Action</th><th scope="col">Target</th></tr></thead><tbody>${(data.audit||[]).slice(-30).reverse().map(a=>`<tr><td>${escape(date(a.createdAt||a.at||a.timestamp))}</td><td>${escape(a.actor||a.identity)}</td><td>${escape(a.action)}</td><td>${escape(a.target||a.studyId)}</td></tr>`).join('')}</tbody></table></div></section><div class="integration"><strong>Directory integration · Not configured</strong>Production identity and revocation require on-premises validation. Demo identities are restricted to local development.</div><div class="integration"><strong>External integrations · Disabled</strong>AI and Teams are disabled. No external traffic is generated.</div></div>`;}
$('#identity').addEventListener('change',async e=>{e.target.disabled=true;++state.route;state.search=null;$('#main').innerHTML='<p role="status">Switching synthetic identity…</p>';try{await api('/api/session',{identity:e.target.value});await refreshSession();location.hash='#studies';await route();notice('Demo identity changed. Accessible studies have been refreshed.');}catch(error){notice(error.message,true);}finally{e.target.disabled=false;}});
$('#search-form').addEventListener('submit',event=>{event.preventDefault();const query=$('#search').value.trim();loadSearchPage(query,1,{});});
document.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(!button)return;const source=items().find(i=>i.id===button.dataset.id);if(button.dataset.action==='cancel'){$('#editor').innerHTML='';$('.content-heading button')?.focus();}if(button.dataset.action==='new')showEditor(button.dataset.kind);if(button.dataset.action==='upload')showUploadEditor();if(button.dataset.action==='attach')showUploadEditor(source?.id);if(button.dataset.action==='file-version')showUploadEditor(null,liveFiles().find(f=>f.id===button.dataset.file));if(button.dataset.action==='document-state')showDocumentStateEditor(source,button.dataset.state);if(button.dataset.action==='supersede-decision')showDecisionEditor(source,true);if(button.dataset.action==='edit-task')showTaskEditor(source);if(button.dataset.action==='reply')showEditor('reply',source);if(button.dataset.action==='decision')showEditor('decision',source);if(button.dataset.action==='revise')showEditor(source.kind,source,true);});
document.addEventListener('submit',async e=>{const form=e.target;if(!['item-form','document-form','document-state-form','task-form','protocol-form','upload-form','stage-form','mapping-form','role-form'].includes(form.id))return;e.preventDefault();const submit=$('button[type=submit]',form);submit.disabled=true;const fields=Object.fromEntries(new FormData(form));try{if(form.id==='document-form'){await api(`/api/studies/${encodeURIComponent(state.study.id)}/documents${form.dataset.previous?'/'+encodeURIComponent(form.dataset.previous)+'/versions':''}`,{title:fields.title,body:fields.body,templateId:form.dataset.template||null,templateVersionId:form.dataset.templateVersion||null,fileIds:new FormData(form).getAll('fileIds'),expectedRevision:Number(form.dataset.revision),requestId:form.dataset.request});}else if(form.id==='document-state-form'){await api(`/api/studies/${encodeURIComponent(state.study.id)}/documents/${encodeURIComponent(form.dataset.version)}/state`,{status:form.dataset.state,reason:fields.reason,expectedRevision:Number(form.dataset.revision),requestId:form.dataset.request});}else if(form.id==='protocol-form'){const [kind,id]=fields.selection?fields.selection.split(':'):[null,null];await api(`/api/studies/${encodeURIComponent(state.study.id)}/protocol`,{kind,id,reason:fields.reason,expectedRevision:Number(form.dataset.revision),requestId:form.dataset.request});}else if(form.id==='upload-form'){const file=$('#upload-file').files[0];if(!file||file.size>512*1024)throw new Error('Choose a synthetic file no larger than 512 KiB.');const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(const byte of bytes)binary+=String.fromCharCode(byte);await api(`/api/studies/${encodeURIComponent(state.study.id)}/files`,{name:file.name,contentBase64:btoa(binary),parentId:form.dataset.parent||null,documentId:form.dataset.file||null,expectedRevision:state.study.revision,requestId:form.dataset.request});}else if(form.id==='task-form'){await api(`/api/studies/${encodeURIComponent(state.study.id)}/tasks${form.dataset.task?'/'+encodeURIComponent(form.dataset.task):''}`,{...fields,assignee:fields.assignee||null,dueDate:fields.dueDate||null,links:new FormData(form).getAll('links'),fileLinks:new FormData(form).getAll('fileLinks'),expectedRevision:state.study.revision,requestId:form.dataset.request});}else if(form.id==='item-form'){await api(`/api/studies/${encodeURIComponent(state.study.id)}/items`,{...fields,fileIds:new FormData(form).getAll('fileIds'),kind:form.dataset.kind,parentId:fields.parentId||form.dataset.parent||null,documentId:fields.documentId||form.dataset.document||null,expectedRevision:state.study.revision,requestId:form.dataset.request});}else if(form.id==='stage-form'){await api(`/api/studies/${encodeURIComponent(state.study.id)}/stage`,{...fields,expectedRevision:state.study.revision,requestId:crypto.randomUUID()});}else await api('/api/admin/'+(form.id==='role-form'?'role':'mapping'),{...fields,expectedRevision:Number(form.dataset.revision),requestId:form.dataset.request});await refreshSession();if(form.id==='document-form'&&form.dataset.template)history.replaceState(null,'',`#study/${encodeURIComponent(state.study.id)}/document`);await route();$('#main').focus();notice('Saved. The shared record has been updated.');}catch(error){notice(error.message,true);const local=$('#form-error');if(local)local.textContent='Your draft is still here. If the workspace changed, copy your text before refreshing.';}finally{submit.disabled=false;}});
window.addEventListener('hashchange',()=>{route().then(()=>{if(!location.hash.slice(1).split('/')[3])$('#main').focus();});});
$('#main').innerHTML='<p role="status">Loading your accessible study workspace…</p>';
refreshSession().then(route).catch(error=>{$('#main').innerHTML=`<div class="panel empty"><h1>Unable to load the local demo</h1><p>${escape(error.message)}</p><p>Verify the application is running in Development on loopback.</p></div>`;});

function taskMetadata(item){
 const task=item.task;
 if(!task)return '<p class="screen-note">Legacy task note · update this task to add structured ownership and status.</p>';
 const person=state.session.identities.find(i=>i.id===task.assignee);
 return `<div class="task-facts"><span class="pill">${escape(task.status)}</span><span>Owner: ${escape(person?.name||task.assignee||'Unassigned')}</span><span>Due: ${escape(task.dueDate||'Not set')}</span></div>${task.links.length?`<p class="screen-note">Evidence: ${task.links.map(itemEvidence).join(' · ')}</p>`:''}${fileEvidence(task.fileLinks||[])}${task.history.length?`<details class="task-history"><summary>Task history (${task.history.length} previous ${task.history.length===1?'revision':'revisions'})</summary>${task.history.slice().reverse().map(v=>`<div class="reply"><p class="record-meta">Revision ${v.version} · ${escape(v.actor)} · ${date(v.at)}</p><h4>${escape(v.title)}</h4><p>${escape(v.body)}</p><p class="screen-note">${escape(v.status)} · Owner: ${escape(v.assignee||'Unassigned')} · Due: ${escape(v.dueDate||'Not set')}</p><p class="screen-note">Evidence: ${v.links.map(itemEvidence).join(' · ')||'None'}</p>${fileEvidence(v.fileLinks||[])}</div>`).join('')}</details>`:''}`;
}
async function showTaskEditor(source=null){
 const studyId=state.study.id;
 try{
 const assignees=await api(`/api/studies/${encodeURIComponent(studyId)}/assignees`);
 if(state.study?.id!==studyId||!$('#editor'))return;
 const task=source?.task;
 const links=task?.links||[source?.documentId].filter(Boolean);
 $('#editor').innerHTML=`<section class="form-panel"><h3>${source?'Update task':'Add task'}</h3><form id="task-form" data-task="${escape(source?.id||'')}" data-request="${crypto.randomUUID()}"><label class="usa-label" for="item-title">Task title</label><input class="usa-input" id="item-title" name="title" maxlength="180" required value="${escape(source?.title||'')}"><label class="usa-label" for="item-body">Next action and context</label><textarea class="usa-textarea" id="item-body" name="body" required maxlength="20000">${escape(source?.body||'')}</textarea><div class="task-form-grid"><div><label class="usa-label" for="task-assignee">Responsible participant</label><select class="usa-select" id="task-assignee" name="assignee"><option value="">Unassigned</option>${assignees.map(i=>`<option value="${escape(i.id)}" ${i.id===task?.assignee?'selected':''}>${escape(i.name)}</option>`).join('')}</select></div><div><label class="usa-label" for="task-status">Status</label><select class="usa-select" id="task-status" name="status">${['Open','In progress','Blocked','Done'].map(status=>`<option ${status===task?.status?'selected':''}>${status}</option>`).join('')}</select></div><div><label class="usa-label" for="task-due">Due date (optional)</label><input class="usa-input" id="task-due" name="dueDate" type="date" min="1900-01-01" max="2100-12-31" value="${escape(task?.dueDate||'')}"></div></div><p class="form-hint">Only current study-group participants can be assigned. Assignment never grants access.</p><fieldset class="evidence-picker"><legend>Supporting records (optional)</legend>${items().filter(i=>['document','documentation','discussion','reply','decision','idea'].includes(i.kind)).map(i=>`<label><input type="checkbox" name="links" value="${escape(i.id)}" ${links.includes(i.id)?'checked':''}> ${escape(i.title)} · ${escape(i.kind)}${i.version?' v'+i.version:''}</label>`).join('')||'<p class="screen-note">No supporting records yet.</p>'}</fieldset>${fileEvidencePicker('fileLinks',task?.fileLinks||[])}<div class="form-row"><button class="usa-button" type="submit">Save task</button><button class="text-button" type="button" data-action="cancel">Cancel</button></div><p id="form-error" class="form-hint" role="alert"></p></form></section>`;
 $('#item-title').focus();
 }catch(error){notice(error.message,true);}
}

function fileRecord(file){
 const released=file.status==='DemoReleased';
 return `<article class="file-record" id="record-${escape(file.id)}" tabindex="-1"><div class="row-head"><strong>${escape(file.name)}</strong><span class="pill ${released?'':'paused'}">${released?'Demo released':'Quarantined'}</span></div><p class="record-meta">File version ${file.version} · ${(file.size/1024).toFixed(1)} KiB · ${escape(file.author)} · ${date(file.createdAt)}</p><p class="screen-note">${released?'Passed the narrow synthetic demonstration policy. This is not a malware scan.':'Download blocked. This file has not been released by the synthetic demonstration policy.'}</p><div class="record-actions">${released?`<a href="/api/studies/${encodeURIComponent(state.study.id)}/files/${encodeURIComponent(file.id)}/download">Download ${escape(file.name)}</a>`:'<span class="screen-note">Download unavailable while quarantined</span>'}<button class="text-button" data-action="file-version" data-file="${escape(file.id)}">Upload new version</button></div>${provenanceDetails(file)}<details class="file-details"><summary>File integrity and context</summary><p class="screen-note">SHA-256: <code>${escape(file.sha256)}</code></p><p class="screen-note">${file.parentId?'Attached to: '+escape(items().find(i=>i.id===file.parentId)?.title||'Unavailable discussion'):'Document library file'} · Family: <code>${escape(file.familyId)}</code></p></details></article>`;
}
function showUploadEditor(parentId=null,source=null){
 const editor=$('#editor');if(!editor)return;
 editor.innerHTML=`<section class="form-panel"><h3>${source?'Upload a new file version':'Upload synthetic file'}</h3><form id="upload-form" data-parent="${escape(source?.parentId||parentId||'')}" data-file="${escape(source?.id||'')}" data-request="${crypto.randomUUID()}"><label class="usa-label" for="upload-file">Choose file</label><input class="usa-file-input" id="upload-file" name="file" type="file" accept=".txt,.pdf,.png,.jpg" required aria-describedby="upload-hint"><p id="upload-hint" class="form-hint">Synthetic TXT, PDF, PNG, or JPG only; 512 KiB maximum. All files begin behind the release policy. A demo setting may release UTF-8 text and the bundled synthetic PNG; other binaries remain quarantined. No malware scanner is connected.</p>${source?`<p class="screen-note">New version of ${escape(source.name)}. Prior versions remain available with their existing release status.</p>`:''}${parentId||source?.parentId?`<p class="screen-note">Attached to: ${escape(items().find(i=>i.id===(source?.parentId||parentId))?.title||'Discussion')}</p>`:''}<div class="form-row"><button class="usa-button" type="submit">Upload file</button><button class="text-button" type="button" data-action="cancel">Cancel</button></div><p id="form-error" class="form-hint" role="alert"></p></form></section>`;
 $('#upload-file').focus();
}

function fileIsAvailable(file){return !file.deleted&&file.status==='DemoReleased'&&(!file.parentId||items().some(i=>i.id===file.parentId));}
function itemEvidence(id){const item=items().find(i=>i.id===id);if(!item||(item.kind==='reply'&&!items().some(i=>i.id===item.parentId)))return `<span>Unavailable record (${escape(id)})</span>`;const label=`${escape(item.title)} · ${escape(item.kind)} version ${item.version}`;if(item.boardIdea)return `<a href="#study/${encodeURIComponent(state.study.id)}/idea/board-${encodeURIComponent(item.boardIdea.boardId)}/${encodeURIComponent(item.id)}">${label}</a>`;if(item.kind==='document')return `<a href="/api/studies/${encodeURIComponent(state.study.id)}/documents/${encodeURIComponent(id)}/download">${label}</a>`;const view=item.kind==='reply'?'discussion':item.kind==='decision'?'task':item.kind==='resource'?'documentation':item.kind;return `<a href="#study/${encodeURIComponent(state.study.id)}/${view}/${encodeURIComponent(item.id)}">${label}</a>`;}

function fileEvidence(ids){return ids.length?`<div class="evidence-links"><span class="screen-note">Exact file evidence</span><ul>${ids.map(id=>{const file=(state.study.files||[]).find(f=>f.id===id);return `<li>${file&&fileIsAvailable(file)?`<a href="/api/studies/${encodeURIComponent(state.study.id)}/files/${encodeURIComponent(id)}/download">${escape(file.name)} · file version ${file.version}</a>`:`Unavailable file version (${escape(id)})`}</li>`;}).join('')}</ul></div>`:'';}
function fileEvidencePicker(name,selected=[]){const available=liveFiles().filter(fileIsAvailable);return `<fieldset class="evidence-picker"><legend>Exact file versions (optional)</legend>${available.map(file=>`<label><input type="checkbox" name="${name}" value="${escape(file.id)}" ${selected.includes(file.id)?'checked':''}> ${escape(file.name)} · file version ${file.version}</label>`).join('')||'<p class="screen-note">No released file versions available.</p>'}${selected.filter(id=>!available.some(f=>f.id===id)).map(id=>`<p class="screen-note">Previously linked file is unavailable (${escape(id)}). Saving will remove this citation from the new revision; history preserves it.</p>`).join('')}</fieldset>`;}
function protocolPanel(edit=false){
 const selected=state.study.currentProtocol;
 const selectionLabel=entry=>!entry?.kind?'No protocol designated':entry===selected&&state.protocolAvailability?.available===false?`<span>Unavailable designated ${escape(entry.kind)} version (${escape(entry.id)})</span>`:entry.kind==='item'?itemEvidence(entry.id):fileReference(entry.id);
 return `<section class="panel accent-panel"><h2 class="label">Current protocol · exact version</h2>${selected?`<div class="protocol-title">${selectionLabel(selected)}</div><p class="screen-note">Selected by ${escape(selected.actor)} · ${date(selected.at)}</p><p>${escape(selected.reason)}</p>`:'<h3>No current protocol selected</h3><p class="muted">Choose an exact document version when the team agrees its working reference.</p>'}${selected?.kind==='item'?`<p class="screen-note">Document state: ${escape(state.documentWorkspace?.versions.find(v=>v.item.id===selected.id)?.status||'Unavailable')}</p>`:''}${selected&&state.protocolAvailability?.available===false?`<p class="notice error">${escape(state.protocolAvailability.error)}</p>`:''}<p class="screen-note">A workspace designation is not external study approval. Uploading a later version does not change this selection.</p>${edit?`<form id="protocol-form" data-revision="${state.study.revision}" data-request="${crypto.randomUUID()}"><label for="protocol-selection" class="usa-label">Current protocol version</label><select class="usa-select" id="protocol-selection" name="selection"><option value="">Clear current designation</option>${items('document').map(item=>`<option value="item:${escape(item.id)}" ${selected?.kind==='item'&&selected.id===item.id?'selected':''}>${escape(item.title)} · text version ${item.version}</option>`).join('')}${liveFiles().filter(f=>!f.parentId&&fileIsAvailable(f)).map(file=>`<option value="file:${escape(file.id)}" ${selected?.kind==='file'&&selected.id===file.id?'selected':''}>${escape(file.name)} · file version ${file.version}</option>`).join('')}</select><label class="usa-label" for="protocol-reason">Reason for selection or clearing</label><textarea class="usa-textarea" id="protocol-reason" name="reason" required maxlength="1000"></textarea><div class="form-row"><button class="usa-button" type="submit">Save protocol designation</button></div></form><details class="task-history"><summary>Protocol designation history (${(state.study.protocolHistory||[]).length})</summary>${(state.study.protocolHistory||[]).slice().reverse().map(entry=>`<div class="reply"><p>${selectionLabel(entry)}</p><p>${escape(entry.reason)}</p><p class="record-meta">${escape(entry.actor)} · ${date(entry.at)}</p></div>`).join('')||'<p>No prior designation events.</p>'}</details>`:linkView('activity','Manage protocol designation')}</section>`;
}

let importDraft=null;
function importPanel(){if(state.session.user.role!=='Administrator')return '';return `<section class="panel"><h2>Synthetic import rehearsal</h2><p class="screen-note">Requires application administration and current study-group membership. Only synthetic manifests are accepted. Preview accounts for every input record; unresolved records are quarantined, not silently published.</p><form id="import-preview-form"><label class="usa-label" for="import-file">Synthetic manifest JSON</label><input class="usa-file-input" type="file" id="import-file" accept=".json,application/json" required><p class="form-hint">Choose the bundled fixtures/app-import.json or a synthetic manifest in the same schema. No live source connection or real migration is performed.</p><div class="form-row"><button class="usa-button" type="submit">Preview import</button></div></form><div id="import-preview" aria-live="polite"></div><div id="import-review-workspace" tabindex="-1" aria-live="polite"><p class="screen-note">Loading exception review…</p></div><details class="task-history"><summary>Saved import reports</summary><div id="import-reports">Loading reports…</div></details></section>`;}
function renderImportReport(report){const counts=report.counts||{};return `<div class="import-report"><h3>${report.applied?'Applied report':'Preview report'}</h3><p class="screen-note">${report.inputCount} input records · Study revision ${report.studyRevision} · ${date(report.at)}</p><dl class="import-counts">${Object.entries(counts).map(([key,value])=>`<div><dt>${escape(key.replaceAll('_',' '))}</dt><dd>${escape(value)}</dd></div>`).join('')}</dl><p class="screen-note">Quarantined outcomes require correction before they can become study content. A successful apply may include both accepted and quarantined records.</p><ul class="import-outcomes">${(report.outcomes||[]).map(outcome=>`<li><strong>${escape(outcome.sourceId||'Unidentified input')}</strong> · ${escape(outcome.status)}${outcome.reasons?.length?`<p>${outcome.reasons.map(escape).join('; ')}</p>`:''}</li>`).join('')}</ul><details><summary>Manifest integrity</summary><code>${escape(report.manifestSha256)}</code></details></div>`;}
async function loadImportReports(){const id=state.study?.id;const routeTicket=state.route;try{const [reports,review,members]=await Promise.all([api(`/api/studies/${encodeURIComponent(id)}/imports`),api(`/api/studies/${encodeURIComponent(id)}/imports/review`),api(`/api/studies/${encodeURIComponent(id)}/assignees`)]);if(state.route!==routeTicket||state.study?.id!==id||!$('#import-reports'))return;state.importReview={...review,reports,members};$('#import-reports').innerHTML=reports.length?reports.slice().reverse().map(report=>renderImportReport(report)+`<button class="usa-button usa-button--outline" data-import-receipt="${escape(report.id)}">Capture batch receipt</button>`).join(''):'<p class="screen-note">No import reports saved.</p>';renderImportReview();}catch(error){if(state.route===routeTicket&&state.study?.id===id){if($('#import-reports'))$('#import-reports').textContent=error.message;if($('#import-review-workspace'))$('#import-review-workspace').innerHTML=`<p class="notice error">Exception review unavailable: ${escape(error.message)}</p>`;}}}
document.addEventListener('submit',async event=>{
 const form=event.target;if(form.id!=='import-preview-form')return;event.preventDefault();const button=$('button',form);button.disabled=true;importDraft=null;
 try{const file=$('#import-file').files[0];if(!file||file.size>512*1024)throw new Error('Choose a synthetic JSON manifest no larger than 512 KiB.');const manifest=JSON.parse(await file.text());const studyId=state.study.id;const report=await api(`/api/studies/${encodeURIComponent(studyId)}/imports/preview`,{manifest});if(state.study?.id!==studyId||!$('#import-preview'))return;importDraft={manifest,expectedRevision:report.studyRevision,requestId:crypto.randomUUID(),studyId};$('#import-preview').innerHTML=renderImportReport(report)+'<p class="screen-note">Review all outcomes before applying. This writes accepted synthetic records and saves the report.</p><button class="usa-button" type="button" id="apply-import">Apply previewed manifest</button>';
 }catch(error){notice(error.message,true);}finally{button.disabled=false;}
});
document.addEventListener('click',async event=>{
 if(event.target.id!=='apply-import'||!importDraft)return;const button=event.target;button.disabled=true;
 try{const draft=importDraft;const report=await api(`/api/studies/${encodeURIComponent(draft.studyId)}/imports/apply`,{manifest:draft.manifest,expectedRevision:draft.expectedRevision,requestId:draft.requestId});importDraft=null;await route();notice('Synthetic import applied. Review accepted and quarantined outcomes in the saved report.');if($('#import-preview'))$('#import-preview').innerHTML=renderImportReport(report);
 }catch(error){notice(error.message+' The preview is retained; do not apply against a changed study without reviewing a fresh preview.',true);}finally{button.disabled=false;}
});

function fileReference(id){const file=(state.study.files||[]).find(f=>f.id===id);return file&&fileIsAvailable(file)?`<a href="/api/studies/${encodeURIComponent(state.study.id)}/files/${encodeURIComponent(id)}/download">${escape(file.name)} · file version ${file.version}</a>`:`<span>Unavailable file version (${escape(id)})</span>`;}

function provenanceDetails(record){const source=record.provenance;if(!source)return '';return `<details class="source-provenance"><summary>Historical source provenance</summary><dl><dt>Source workspace</dt><dd>${escape(source.sourceStudyId)}</dd><dt>Source record / revision</dt><dd>${escape(source.sourceId)} / ${escape(source.sourceRevision)}</dd><dt>Original author</dt><dd>${escape(record.author)}</dd><dt>Original time</dt><dd><time datetime="${escape(record.createdAt)}">${escape(record.createdAt)}</time></dd></dl>${source.referenceTargetIds?.length?`<p class="screen-note">Preserved source references</p><ul>${source.referenceTargetIds.map(id=>`<li>${(state.study.files||[]).some(file=>file.id===id)?fileReference(id):itemEvidence(id)}</li>`).join('')}</ul>`:''}<p class="screen-note">Historical attribution does not grant current access.</p></details>`;}

function documentInfo(item){return state.documentWorkspace?.versions.find(version=>version.item.id===item.id);}
function documentReviewSummary(item){const version=documentInfo(item);return `<div class="task-facts"><span class="pill">${escape(version?.status||'Draft')}</span><span>Family ${escape(version?.familyId||item.id)}</span></div><p class="screen-note">Internal document review state; not external study approval. File citations are verified again at acceptance and download.</p>${version?.history.length?`<details class="task-history"><summary>Review history (${version.history.length})</summary>${version.history.map(event=>`<div class="reply"><strong>${escape(event.from)} → ${escape(event.to)}</strong><p>${escape(event.reason)}</p><p class="record-meta">${escape(event.actor)} · ${date(event.at)}</p></div>`).join('')}</details>`:''}`;}
function documentStateActions(item){const info=documentInfo(item);const role=state.documentWorkspace?.studyRole;const buttons=[];if((info?.status||'Draft')==='Draft'&&role!=='None')buttons.push(['Review','Submit for review']);if(info?.status==='Review'&&['Reviewer','StudyLead'].includes(role))buttons.push(['Draft','Return to draft']);if(info?.status==='Review'&&role==='StudyLead')buttons.push(['Accepted','Accept version']);if(info?.status==='Accepted'&&role==='StudyLead')buttons.push(['Superseded','Supersede version']);return buttons.map(([status,label])=>`<button class="text-button" data-action="document-state" data-state="${status}" data-id="${escape(item.id)}">${label}</button>`).join('');}
function documentFamilies(){const families=new Map();for(const version of state.documentWorkspace?.versions||[]){if(!families.has(version.familyId))families.set(version.familyId,[]);families.get(version.familyId).push(version);}return [...families.values()].map(versions=>{versions.sort((a,b)=>b.item.version-a.item.version);const protocol=state.study.currentProtocol;const visible=versions.filter((version,index)=>index===0||version.status==='Accepted'||(protocol?.kind==='item'&&protocol.id===version.item.id));const history=versions.filter(version=>!visible.includes(version));return `<section class="document-family"><div class="family-heading"><h3>${escape(versions[0].item.title)}</h3><span class="family-count">${versions.length} immutable ${versions.length===1?'version':'versions'}</span></div><p class="screen-note">Latest, accepted, and designated versions are shown first. Your study role: ${escape(state.documentWorkspace.studyRole)}.</p>${visible.map(version=>record(version.item)).join('')}${history.length?`<details class="version-disclosure" data-document-family="${escape(versions[0].familyId)}"><summary>Retained document history (${history.length})<span class="usa-sr-only"> for ${escape(versions[0].item.title)}</span></summary><p class="screen-note">Exact earlier content, attribution, evidence, and review history remain available.</p>${history.map(version=>record(version.item)).join('')}</details>`:''}</section>`;}).join('');}
function fileFamilies(){const families=new Map();for(const file of liveFiles()){const family=file.familyId||file.id;if(!families.has(family))families.set(family,[]);families.get(family).push(file);}return [...families.entries()].map(([family,versions])=>{versions.sort((a,b)=>b.version-a.version||new Date(b.createdAt)-new Date(a.createdAt));const protocol=state.study.currentProtocol;const newestReleased=versions.find(file=>fileIsAvailable(file));const visible=versions.filter((file,index)=>index===0||(protocol?.kind==='file'&&protocol.id===file.id)||(versions[0].status!=='DemoReleased'&&file===newestReleased));const history=versions.filter(file=>!visible.includes(file));return `<section class="file-family"><div class="family-heading"><h4>${escape(versions[0].name)}</h4><span class="family-count">${versions.length} ${versions.length===1?'file version':'file versions'}</span></div>${visible.map(fileRecord).join('')}${history.length?`<details class="version-disclosure" data-file-family="${escape(family)}"><summary>Retained file history (${history.length})<span class="usa-sr-only"> for ${escape(versions[0].name)}</span></summary><p class="screen-note">Each download points to its exact stored version; release status still applies.</p>${history.map(fileRecord).join('')}</details>`:''}</section>`;}).join('');}

function showDocumentEditor(source,revision,template=null){const editor=$('#editor');if(!editor)return;editor.innerHTML=`<section class="form-panel"><h3>${revision?'Create immutable document version':'Create document family'}</h3>${template?`<p class="screen-note">Template: ${escape(template.title)} · Definition version ${escape(template.version||1)}. Edit the suggested content before creating your Draft document.</p>`:''}<form id="document-form" data-template="${escape(template?.id||'')}" data-template-version="${escape(template?.versionId||'')}" data-previous="${revision?escape(source.id):''}" data-revision="${state.study.revision}" data-request="${crypto.randomUUID()}"><label class="usa-label" for="item-title">Document title</label><input class="usa-input" id="item-title" name="title" required maxlength="180" value="${revision||template?escape(source.title):''}"><label class="usa-label" for="item-body">Version content</label><textarea class="usa-textarea" id="item-body" name="body" required maxlength="20000">${revision||template?escape(source.body):''}</textarea><p class="form-hint">Saves a new Draft version with its own author and time. Earlier content and review history remain unchanged; renaming does not change the document family.</p>${fileEvidencePicker('fileIds',revision?source.fileIds||[]:[])}<div class="form-row"><button class="usa-button" type="submit">Save draft version</button><button class="text-button" type="button" data-action="cancel">Cancel</button></div><p id="form-error" class="form-hint" role="alert"></p></form></section>`;$('#item-title').focus();}
function showDocumentStateEditor(item,status){$('#editor').innerHTML=`<section class="form-panel"><h3>${escape(item.title)} → ${escape(status)}</h3><form id="document-state-form" data-version="${escape(item.id)}" data-state="${status}" data-revision="${state.study.revision}" data-request="${crypto.randomUUID()}"><label class="usa-label" for="document-state-reason">Reason for review-state change</label><textarea class="usa-textarea" name="reason" id="document-state-reason" required maxlength="1000"></textarea><p class="form-hint">This records an internal study-document decision. It does not grant external approval or change the current protocol selection.</p><div class="form-row"><button class="usa-button" type="submit">Confirm ${escape(status)}</button><button class="text-button" type="button" data-action="cancel">Cancel</button></div><p id="form-error" class="form-hint" role="alert"></p></form></section>`;$('#document-state-reason').focus();}
function handoffWorkspace(){return `<div class="content-heading"><h2>Handoff snapshots</h2></div><p class="section-description">Capture a fixed study packet for orientation or handoff. Later edits do not rewrite it; current access and source-removal restrictions still apply.</p><section class="panel"><h3>Capture a handoff</h3><form id="handoff-form" data-revision="${state.study.revision}" data-request="${crypto.randomUUID()}"><label class="usa-label" for="handoff-title">Snapshot title</label><input class="usa-input" id="handoff-title" name="title" required maxlength="180"><label class="usa-label" for="handoff-summary">Scope, assumptions, open questions, and owners</label><textarea class="usa-textarea" id="handoff-summary" name="summary" required maxlength="2000"></textarea><label class="usa-label" for="handoff-mode">Evidence selection</label><select class="usa-select" id="handoff-mode" name="mode"><option value="default">Default study packet with linked evidence</option><option value="explicit">Only explicitly checked records and files below</option></select><details class="task-history"><summary>Choose explicit evidence (optional)</summary><fieldset class="evidence-picker"><legend>Study records</legend>${items().filter(item=>['document','documentation','decision','task','discussion','reply','idea','resource'].includes(item.kind)).map(item=>`<label><input type="checkbox" name="itemIds" value="${escape(item.id)}">${escape(item.title)} · ${escape(item.kind)} version ${item.version}</label>`).join('')}</fieldset>${fileEvidencePicker('fileIds',[])}</details><p class="form-hint">Default capture includes current study guidance, decisions, tasks, conversations, protocol, and linked evidence. If a file is quarantined or evidence unavailable, choose an explicit set of available records and files. Linked evidence is always included. Capturing a snapshot is not formal approval.</p><div class="form-row"><button class="usa-button" type="submit">Capture snapshot</button></div><p id="handoff-error" class="form-hint" role="alert"></p></form></section><section class="panel"><h3>Saved snapshots</h3><div id="handoff-list">Loading snapshots…</div></section><div id="handoff-detail"></div>`;}
async function loadHandoffs(){const studyId=state.study?.id;const routeTicket=state.route;try{const snapshots=await api(`/api/studies/${encodeURIComponent(studyId)}/handoffs`);if(state.study?.id!==studyId||state.route!==routeTicket||!$('#handoff-list'))return;$('#handoff-list').innerHTML=snapshots.length?snapshots.slice().reverse().map(snapshot=>`<article class="record"><h3>${escape(snapshot.title)}</h3><p>${escape(snapshot.summary)}</p><p class="record-meta">${escape(snapshot.createdBy)} · ${date(snapshot.createdAt)} · Study revision ${snapshot.sourceRevision} · ${snapshot.itemCount} records / ${snapshot.fileCount} files</p><button class="text-button" data-action="view-handoff" data-snapshot="${escape(snapshot.id)}">View snapshot</button></article>`).join(''):'<p class="muted">No snapshots yet.</p>';}catch(error){if(state.route===routeTicket&&state.study?.id===studyId&&$('#handoff-list'))$('#handoff-list').textContent=error.message;}}
function renderHandoff(snapshot){const evidence=id=>{const captured=snapshot.items.find(entry=>entry.item?.id===id);if(captured)return captured.available?`${escape(captured.item.title)} · ${escape(captured.item.kind)} version ${captured.item.version}`:'Unavailable captured record';const file=snapshot.files.find(entry=>entry.file?.id===id);return file?.available?`<a href="/api/studies/${encodeURIComponent(state.study.id)}/files/${encodeURIComponent(id)}/download">${escape(file.file.name)} · file version ${file.file.version}</a>`:'Unavailable captured evidence';};return `<section class="panel handoff-capture" tabindex="-1"><p class="eyebrow">Immutable handoff capture</p><h2>${escape(snapshot.title)}</h2><p>${escape(snapshot.summary)}</p><p class="record-meta">${escape(snapshot.createdBy)} · ${escape(snapshot.createdAt)} · Source revision ${snapshot.sourceRevision}</p><p class="screen-note">${escape(snapshot.studyTitle)} · Captured workspace stage: ${escape(snapshot.studyStage)}</p>${snapshot.redacted?'<div class="notice error">Some captured sources are now unavailable. Their restricted content is omitted from this view.</div>':''}<div class="integration"><strong>Captured protocol reference</strong>${snapshot.currentProtocol?`${snapshot.protocolAvailable?evidence(snapshot.currentProtocol.id):'Unavailable captured protocol'}<p>${escape(snapshot.currentProtocol.reason)}</p>`:'No protocol designated at capture.'}</div><h3 class="handoff-section-heading">Captured study records</h3>${snapshot.items.map(entry=>entry.available?`<article class="record"><p class="record-meta">${escape(entry.item.kind)} · Version ${entry.item.version} · ${escape(entry.item.author)} · ${escape(entry.item.createdAt)}</p><h3>${escape(entry.item.title)}</h3>${entry.review?`<span class="pill">Captured state: ${escape(entry.review.status)}</span>${capturedReviewHistory(entry.review)}`:''}${capturedProvenance(entry.item,evidence)}${entry.item.kind==='decision'?capturedDecisionMetadata(entry.item,entry.decision,evidence):''}${entry.item.kind==='resource'?capturedResourceMetadata(entry.item):''}<p>${escape(entry.item.body)}</p>${entry.item.task?`<p class="screen-note">Captured task: ${escape(entry.item.task.status)} · Owner: ${escape(entry.item.task.assignee||'Unassigned')} · Due: ${escape(entry.item.task.dueDate||'Not set')}</p>`:''}<p class="screen-note">${[entry.item.documentId,...(entry.item.fileIds||[]),...(entry.item.task?.links||[]),...(entry.item.task?.fileLinks||[]),...(entry.item.decision?.itemIds||[]),...(entry.item.decision?.fileIds||[])].filter(Boolean).map(evidence).join(' · ')}</p></article>`:`<article class="record"><h3>Unavailable captured record</h3><p>${escape(entry.reason||'Current source restrictions apply.')}</p></article>`).join('')}<h3 class="handoff-section-heading">Captured file versions</h3>${snapshot.files.map(entry=>entry.available?`<article class="record"><h3>${evidence(entry.file.id)}</h3><p class="record-meta">${escape(entry.file.author)} · ${escape(entry.file.createdAt)} · ${entry.file.size} bytes</p><p class="screen-note">SHA-256 <code>${escape(entry.file.sha256)}</code></p>${capturedProvenance(entry.file,evidence)}</article>`:`<article class="record"><h3>Unavailable captured file</h3><p>${escape(entry.reason||'Current source restrictions apply.')}</p></article>`).join('')}<details><summary>Capture integrity</summary><p class="screen-note">${escape(snapshot.digestScope)}</p><code>${escape(snapshot.sha256)}</code></details></section>`;}
document.addEventListener('submit',async event=>{const form=event.target;if(form.id!=='handoff-form')return;event.preventDefault();const button=$('button',form);button.disabled=true;try{const fields=new FormData(form);const payload={title:fields.get('title'),summary:fields.get('summary'),expectedRevision:Number(form.dataset.revision),requestId:form.dataset.request};if(fields.get('mode')==='explicit'){payload.itemIds=fields.getAll('itemIds');payload.fileIds=fields.getAll('fileIds');}const snapshot=await api(`/api/studies/${encodeURIComponent(state.study.id)}/handoffs`,payload);await route();if($('#handoff-detail')){$('#handoff-detail').innerHTML=renderHandoff(snapshot);$('.handoff-capture').focus();}notice('Immutable handoff snapshot captured.');}catch(error){notice(error.message,true);$('#handoff-error').textContent='Your input is retained. Review a fresh study revision before retrying a stale capture.';}finally{button.disabled=false;}});
document.addEventListener('click',async event=>{const button=event.target.closest('[data-action="view-handoff"]');if(!button)return;button.disabled=true;try{const snapshot=await api(`/api/studies/${encodeURIComponent(state.study.id)}/handoffs/${encodeURIComponent(button.dataset.snapshot)}`);if($('#handoff-detail')){$('#handoff-detail').innerHTML=renderHandoff(snapshot);$('.handoff-capture').focus();}}catch(error){notice(error.message,true);}finally{button.disabled=false;}});

function capturedReviewHistory(review){return review.history?.length?`<details class="task-history"><summary>Captured review history (${review.history.length})</summary>${review.history.map(event=>`<div class="reply"><strong>${escape(event.from)} → ${escape(event.to)}</strong><p>${escape(event.reason)}</p><p class="record-meta">${escape(event.actor)} · <time datetime="${escape(event.at)}">${escape(event.at)}</time></p></div>`).join('')}</details>`:'';}
function capturedProvenance(record,resolveEvidence){const source=record.provenance;if(!source)return '';return `<details class="source-provenance"><summary>Captured source provenance</summary><dl><dt>Source workspace</dt><dd>${escape(source.sourceStudyId)}</dd><dt>Source record / revision</dt><dd>${escape(source.sourceId)} / ${escape(source.sourceRevision)}</dd><dt>Original author</dt><dd>${escape(record.author)}</dd><dt>Original time</dt><dd><time datetime="${escape(record.createdAt)}">${escape(record.createdAt)}</time></dd></dl>${source.referenceTargetIds?.length?`<p class="screen-note">References within this capture</p><ul>${source.referenceTargetIds.map(id=>`<li>${resolveEvidence(id)}</li>`).join('')}</ul>`:''}<p class="screen-note">Captured historical attribution does not grant current access.</p></details>`;}
async function loadOnboarding(focusStep=null){const studyId=state.study?.id;const routeTicket=state.route;try{const checklist=await api(`/api/studies/${encodeURIComponent(studyId)}/onboarding`);if(state.study?.id!==studyId||state.route!==routeTicket||!$('#onboarding-panel'))return;state.onboarding=checklist;renderOnboarding(checklist);if(focusStep)document.getElementById('onboarding-'+focusStep)?.focus();}catch(error){if(state.route===routeTicket&&state.study?.id===studyId&&$('#onboarding-panel'))$('#onboarding-panel').innerHTML=`<div class="notice error">Returning-collaborator checklist unavailable: ${escape(error.message)}</div>`;}}
function renderOnboarding(checklist){const available=checklist.steps.filter(step=>step.available);const done=available.filter(step=>step.completed).length;const resume=checklist.steps.find(step=>step.id===checklist.resumeStepId&&step.available&&!step.completed);const contact=typeof checklist.contact==='string'?checklist.contact:checklist.contact?.name||'See study contact';$('#onboarding-panel').innerHTML=`<section class="returning-panel" aria-labelledby="returning-title"><div class="returning-heading"><div><p class="eyebrow">Return with context</p><h2 id="returning-title">Your study orientation</h2><p>Reconnect with the agreed guidance, the latest handoff, open questions, and your next action. This checklist belongs to you.</p></div><span class="returning-count">${done} of ${available.length} available steps complete</span></div>${resume&&String(resume.href).startsWith('#study/')?`<p class="orientation-resume"><a href="${escape(resume.href)}">Continue with: ${escape(resume.label)} <span aria-hidden="true">→</span></a></p>`:available.length&&done===available.length?'<p class="orientation-complete">You have reviewed every currently available step. Return when the study evidence changes.</p>':''}<ul class="returning-checklist">${checklist.steps.map(step=>`<li class="${step.completed?'is-complete':''}"><label for="onboarding-${escape(step.id)}"><input type="checkbox" id="onboarding-${escape(step.id)}" data-onboarding-step="${escape(step.id)}" data-context="${escape(step.contextKey)}" data-request="${crypto.randomUUID()}" ${step.completed?'checked':''} ${step.available?'':'disabled'}><span>${escape(step.label)}<span class="check-description">${escape(step.description)}${step.available?'':' · No available source yet'}${step.completedAt&&step.completed?' · Acknowledged '+date(step.completedAt):''}</span></span></label>${step.available&&String(step.href).startsWith('#study/')?`<a class="small-link" href="${escape(step.href)}">Review <span class="usa-sr-only">${escape(step.label)}</span><span aria-hidden="true"> →</span></a>`:''}</li>`).join('')}</ul><div class="returning-footer"><span>Personal acknowledgment only. It does not approve records or grant access. Changed evidence resets the relevant step.</span><span>Contact: ${escape(contact)}</span></div></section>`;}
document.addEventListener('change',async event=>{const input=event.target;if(!input.matches('[data-onboarding-step]'))return;const stepId=input.dataset.onboardingStep;const desired=input.checked;const studyId=state.study.id;document.querySelectorAll('[data-onboarding-step]').forEach(box=>box.disabled=true);try{await api(`/api/studies/${encodeURIComponent(studyId)}/onboarding`,{stepId,completed:desired,contextKey:input.dataset.context,expectedRevision:state.onboarding.revision,requestId:input.dataset.request});if(state.study?.id===studyId){await loadOnboarding(stepId);notice(desired?'Orientation step acknowledged for the current evidence.':'Orientation acknowledgment cleared.');}}catch(error){input.checked=!desired;notice(error.message+' Your previous acknowledgment has been retained. Refresh to review changed evidence.',true);for(const box of document.querySelectorAll('[data-onboarding-step]'))box.disabled=!state.onboarding.steps.find(step=>step.id===box.dataset.onboardingStep)?.available;input.focus();}});
function brainstormWorkspace(){const legacy=items('idea').filter(item=>!item.boardIdea);return `<div class="content-heading"><h2>Ideas & whiteboards</h2><button class="usa-button" data-board-action="new-session">New session</button></div><div class="brainstorm-intro"><span class="brainstorm-symbol" aria-hidden="true">✳</span><div><h3>Explore together. Keep the reasoning.</h3><p>Named sessions turn early ideas into an ordered, readable record. Every edit keeps its history; decisions cite the exact idea version that informed them.</p></div></div><div id="board-live" class="usa-sr-only" role="status" aria-live="polite"></div><div id="board-editor"></div><div id="board-panel">Loading brainstorming sessions…</div><section class="board-legacy"><div class="row-head"><h3>Legacy idea notes</h3><button class="text-button" data-action="new" data-kind="idea">Capture idea</button></div><p class="screen-note">Earlier standalone notes remain available below. Named sessions above preserve ordering and immutable idea revisions.</p><div id="editor"></div><ol class="idea-list">${legacy.map(item=>`<li><div>${record(item)}</div></li>`).join('')}</ol>${legacy.length?'':'<p class="muted">No standalone legacy notes.</p>'}</section>`;}
async function loadBoards(boardId=null,versionId=null){const studyId=state.study?.id;const routeTicket=state.route;try{const collection=await api(`/api/studies/${encodeURIComponent(studyId)}/boards`);if(state.study?.id!==studyId||state.route!==routeTicket||!$('#board-panel'))return;state.boardCollection=collection;if(boardId){const detail=await api(`/api/studies/${encodeURIComponent(studyId)}/boards/${encodeURIComponent(boardId)}`);if(state.study?.id!==studyId||state.route!==routeTicket||!$('#board-panel'))return;state.activeBoard=detail;renderBoardDetail(detail);if(versionId)focusBoardVersion(detail,versionId);}else{state.activeBoard=null;$('#board-panel').innerHTML=collection.boards.length?`<div class="board-session-grid">${collection.boards.map(board=>`<article class="board-session-card"><span class="pill ${board.status==='Archived'?'paused':''}">${escape(board.status)}</span><h3><a href="#study/${encodeURIComponent(studyId)}/idea/board-${encodeURIComponent(board.id)}">${escape(board.title)}</a></h3><p>${escape(board.purpose)}</p><div class="record-meta"><span>${board.ideaCount} ${board.ideaCount===1?'idea':'ideas'}</span><span>Owner: ${escape(identityName(board.responsibleId))}</span><span>Updated ${date(board.updatedAt)}</span></div></article>`).join('')}</div>`:'<div class="board-empty"><h3>Give the next conversation a shared space</h3><p>Create a named session with a purpose and responsible participant.</p></div>';}}catch(error){if(state.route===routeTicket&&state.study?.id===studyId&&$('#board-panel'))$('#board-panel').innerHTML=`<div class="notice error">${escape(error.message)}</div>`;}}
function identityName(id){return state.session.identities.find(person=>person.id===id)?.name||id||'Unassigned';}
function renderBoardDetail(board,focusIdea=null,announcement=null){const canState=['Reviewer','StudyLead'].includes(board.studyRole);const active=board.status==='Active';const ordered=board.ideaOrder.map(id=>board.ideas.find(idea=>idea.id===id)).filter(Boolean);$('#board-panel').innerHTML=`<section aria-labelledby="board-title"><p class="breadcrumb"><a href="#study/${encodeURIComponent(state.study.id)}/idea">All sessions</a></p><div class="row-head"><div><p class="eyebrow">Brainstorming session</p><h3 id="board-title" tabindex="-1">${escape(board.title)}</h3></div><span class="pill ${active?'':'paused'}">${escape(board.status)}</span></div><p class="board-purpose">${escape(board.purpose)}</p><p class="record-meta">Owner: ${escape(identityName(board.responsibleId))} · ${ordered.length} ordered ideas · Study revision ${board.studyRevision}</p>${state.study.stage!=='Active'?`<div class="notice">This study is ${escape(state.study.stage.toLowerCase())}. Its session record remains readable. ${linkView('activity','Reopen the study in Activity & lifecycle')} before changing session content.</div>`:''}<div class="board-toolbar"><div class="record-actions">${active?'<button class="usa-button" data-board-action="new-idea">Add idea</button>':''}${active?'<button class="text-button" data-board-action="edit-session">Edit session details</button>':''}${canState?`<button class="text-button" data-board-action="state" data-status="${active?'Archived':'Active'}">${active?'Archive session':'Reopen session'}</button>`:''}</div><div class="record-actions"><button class="text-button" data-board-action="summary">Readable summary</button><a class="small-link" href="/api/studies/${encodeURIComponent(state.study.id)}/boards/${encodeURIComponent(board.id)}/export">Download summary</a></div></div>${active?'':'<div class="notice">This session is archived. Its record remains readable; a reviewer or study lead can reopen it.</div>'}<ol class="board-ordered-list">${ordered.map((idea,index)=>boardIdeaCard(idea,index,ordered.length,active)).join('')}</ol>${ordered.length?'':'<div class="board-empty"><h3>Start with a question or a possibility</h3><p>Add the first idea. The list can be reordered entirely with the keyboard.</p></div>'}<details class="source-provenance"><summary>Session activity (${board.history.length})</summary>${board.history.slice().reverse().map(event=>`<div class="recent-item"><strong>${escape(event.action)}</strong><p class="screen-note">${escape(event.actor)} · ${escape(event.at)}</p><p>${escape(event.reason||'')}</p>${boardHistoryChange(event,board)}</div>`).join('')}</details><div id="board-summary"></div></section>`;if(focusIdea)document.getElementById('board-idea-'+focusIdea)?.focus();if(announcement){$('#board-live').textContent=announcement;notice(announcement);}}
function boardIdeaCard(idea,index,count,active){const current=idea.current;return `<li class="board-idea-card" data-idea="${escape(idea.id)}"><span class="board-position" aria-hidden="true">${String(index+1).padStart(2,'0')}</span><div><p class="record-meta">Idea version ${current.version} · ${escape(identityName(current.author))} · ${date(current.createdAt)}</p><h3 id="board-idea-${escape(idea.id)}" tabindex="-1">${escape(current.title)}</h3><p class="board-idea-content">${escape(current.body)}</p><div class="record-actions">${active?`<button class="text-button" data-board-action="edit-idea" data-idea="${escape(idea.id)}">Edit idea</button><button class="board-move" data-board-action="move-up" data-idea="${escape(idea.id)}" ${index===0?'disabled':''} aria-label="Move ${escape(current.title)} up">↑ Move up</button><button class="board-move" data-board-action="move-down" data-idea="${escape(idea.id)}" ${index===count-1?'disabled':''} aria-label="Move ${escape(current.title)} down">↓ Move down</button><button class="text-button" data-board-action="decision" data-idea="${escape(idea.id)}" data-version="${escape(idea.currentVersionId)}">Record decision</button>`:''}</div><details class="source-provenance"><summary>Idea history & decisions (${idea.versions.length} ${idea.versions.length===1?'version':'versions'})</summary>${idea.versions.slice().reverse().map(version=>`<div class="recent-item board-version" id="board-version-${escape(version.item.id)}" tabindex="-1"><strong>${escape(version.item.title)} · Version ${version.item.version}</strong><p class="board-idea-content">${escape(version.item.body)}</p><p class="record-meta">${escape(identityName(version.item.author))} · ${escape(version.item.createdAt)}</p>${version.decisions.length?`<p class="screen-note">Decisions citing this exact version</p><ul>${version.decisions.map(decision=>`<li><a href="#study/${encodeURIComponent(state.study.id)}/task/${encodeURIComponent(decision.id)}">${escape(decision.title)}</a> <span class="pill ${decision.status==='Superseded'?'paused':''}">${escape(decision.status||'State unavailable')}</span>${decision.supersededById?` <a href="#study/${encodeURIComponent(state.study.id)}/task/${encodeURIComponent(decision.supersededById)}">View replacement</a>`:''}</li>`).join('')}</ul>`:'<p class="screen-note">No decision cites this version yet.</p>'}${active?`<button class="text-button" data-board-action="decision" data-idea="${escape(idea.id)}" data-version="${escape(version.item.id)}">Decide from version ${version.item.version}</button>`:''}</div>`).join('')}</details></div></li>`;}
async function showBoardSessionEditor(edit=false){const studyId=state.study.id;try{const members=await api(`/api/studies/${encodeURIComponent(studyId)}/assignees`);if(state.study?.id!==studyId||!$('#board-editor'))return;const board=edit?state.activeBoard:null;$('#board-editor').innerHTML=`<section class="form-panel"><h3>${edit?'Edit session details':'Create brainstorming session'}</h3><form id="board-session-form" data-board="${escape(board?.id||'')}" data-revision="${board?.studyRevision||state.boardCollection?.studyRevision||state.study.revision}" data-request="${crypto.randomUUID()}"><label class="usa-label" for="board-session-title">Session title</label><input class="usa-input" id="board-session-title" name="title" required maxlength="180" value="${escape(board?.title||'')}"><label class="usa-label" for="board-purpose">Session purpose</label><textarea class="usa-textarea" id="board-purpose" name="purpose" required maxlength="4000">${escape(board?.purpose||'')}</textarea><label class="usa-label" for="board-owner">Responsible participant</label><select class="usa-select" id="board-owner" name="responsibleId">${members.map(member=>`<option value="${escape(member.id)}" ${member.id===(board?.responsibleId||state.session.user.id)?'selected':''}>${escape(member.name)}</option>`).join('')}</select><p class="form-hint">Responsibility does not grant membership. Participants come from the study's authoritative synthetic group.</p><div class="form-row"><button class="usa-button" type="submit">Save session</button><button class="text-button" type="button" data-board-action="cancel">Cancel</button></div><p class="board-error form-hint" role="alert"></p></form></section>`;$('#board-session-title').focus();}catch(error){notice(error.message,true);}}
function showBoardIdeaEditor(idea=null){const board=state.activeBoard;$('#board-editor').innerHTML=`<section class="form-panel"><h3>${idea?'Add an immutable idea revision':'Capture an idea'}</h3><form id="board-idea-form" data-idea="${escape(idea?.id||'')}" data-revision="${board.studyRevision}" data-request="${crypto.randomUUID()}"><label class="usa-label" for="board-idea-title">Idea title</label><input class="usa-input" id="board-idea-title" name="title" required maxlength="180" value="${escape(idea?.current.title||'')}"><label class="usa-label" for="board-idea-body">Idea content</label><textarea class="usa-textarea" id="board-idea-body" name="body" required maxlength="20000">${escape(idea?.current.body||'')}</textarea><p class="form-hint">Earlier versions and their decision links remain available after editing.</p><div class="form-row"><button class="usa-button" type="submit">Save idea</button><button class="text-button" type="button" data-board-action="cancel">Cancel</button></div><p class="board-error form-hint" role="alert"></p></form></section>`;$('#board-idea-title').focus();}
function showBoardDecisionEditor(idea,versionId){const version=idea.versions.find(entry=>entry.item.id===versionId)?.item;if(!version)return;$('#board-editor').innerHTML=`<section class="form-panel"><h3>Turn an idea into a decision</h3><p class="screen-note">Exact evidence: ${escape(version.title)} · Idea version ${version.version}</p><form id="board-decision-form" data-idea="${escape(idea.id)}" data-version="${escape(versionId)}" data-revision="${state.activeBoard.studyRevision}" data-request="${crypto.randomUUID()}"><label class="usa-label" for="board-decision-title">Decision title</label><input class="usa-input" id="board-decision-title" name="title" maxlength="180" required><label class="usa-label" for="board-decision-rationale">Decision and rationale</label><textarea class="usa-textarea" id="board-decision-rationale" name="rationale" maxlength="20000" required></textarea><p class="form-hint">This records the team's reasoning and exact source revision. It is not external study approval.</p><div class="form-row"><button class="usa-button" type="submit">Save linked decision</button><button class="text-button" type="button" data-board-action="cancel">Cancel</button></div><p class="board-error form-hint" role="alert"></p></form></section>`;$('#board-decision-title').focus();}
function showBoardStateEditor(status){$('#board-editor').innerHTML=`<section class="form-panel"><h3>${status==='Active'?'Reopen':'Archive'} session</h3><form id="board-state-form" data-status="${status}" data-revision="${state.activeBoard.studyRevision}" data-request="${crypto.randomUUID()}"><label class="usa-label" for="board-state-reason">Reason for session-state change</label><textarea class="usa-textarea" id="board-state-reason" name="reason" maxlength="1000" required></textarea><div class="form-row"><button class="usa-button" type="submit">Confirm ${status==='Active'?'reopen':'archive'}</button><button class="text-button" type="button" data-board-action="cancel">Cancel</button></div><p class="board-error form-hint" role="alert"></p></form></section>`;$('#board-state-reason').focus();}
async function updateBoard(path,payload,focusIdea=null,announcement='Session saved.'){const studyId=state.study.id;const routeTicket=state.route;const result=await api(`/api/studies/${encodeURIComponent(studyId)}/boards${path}`,payload);const freshStudy=await api(`/api/studies/${encodeURIComponent(studyId)}`);if(state.study?.id!==studyId||state.route!==routeTicket||!$('#board-panel'))return result;state.study=freshStudy;state.activeBoard=result;state.boardCollection.studyRevision=result.studyRevision;$('#board-editor').innerHTML='';renderBoardDetail(result,focusIdea,announcement);return result;}
document.addEventListener('submit',async event=>{const form=event.target;if(!['board-session-form','board-idea-form','board-decision-form','board-state-form'].includes(form.id))return;event.preventDefault();const button=$('button[type=submit]',form);button.disabled=true;const fields=Object.fromEntries(new FormData(form));const submittedRoute=state.route;const payload={...fields,expectedRevision:Number(form.dataset.revision),requestId:form.dataset.request};try{let path='';let focusIdea=null;let announcement='Session saved.';if(form.id==='board-session-form')path=form.dataset.board?'/'+encodeURIComponent(form.dataset.board):'';else{path='/'+encodeURIComponent(state.activeBoard.id);if(form.id==='board-idea-form'){path+='/ideas'+(form.dataset.idea?'/'+encodeURIComponent(form.dataset.idea)+'/versions':'');focusIdea=form.dataset.idea||null;announcement='Idea saved with its version history.';}if(form.id==='board-decision-form'){path+='/ideas/'+encodeURIComponent(form.dataset.idea)+'/decisions';payload.versionId=form.dataset.version;focusIdea=form.dataset.idea;announcement='Decision saved with an exact idea-version reference.';}if(form.id==='board-state-form'){path+='/state';payload.status=form.dataset.status;announcement=form.dataset.status==='Active'?'Session reopened.':'Session archived. Its history remains available.';}}const result=await updateBoard(path,payload,focusIdea,announcement);if(state.route!==submittedRoute)return;if(!location.hash.includes('/board-'+result.id))location.hash=`#study/${encodeURIComponent(state.study.id)}/idea/board-${encodeURIComponent(result.id)}`;else if(!focusIdea)$('#board-title')?.focus();}catch(error){notice(error.message,true);$('.board-error',form).textContent='Your draft is retained. If the session changed, review a fresh revision before retrying.';}finally{button.disabled=false;}});
document.addEventListener('click',async event=>{const button=event.target.closest('[data-board-action]');if(!button)return;const action=button.dataset.boardAction;const board=state.activeBoard;const idea=board?.ideas.find(entry=>entry.id===button.dataset.idea);if(action==='new-session')return showBoardSessionEditor();if(action==='edit-session')return showBoardSessionEditor(true);if(action==='new-idea')return showBoardIdeaEditor();if(action==='edit-idea')return showBoardIdeaEditor(idea);if(action==='decision')return showBoardDecisionEditor(idea,button.dataset.version);if(action==='state')return showBoardStateEditor(button.dataset.status);if(action==='cancel'){$('#board-editor').innerHTML='';$('#board-title')?.focus();return;}if(action==='summary'){$('#board-summary').innerHTML=`<section class="board-readable" tabindex="-1"><h3>Readable session summary</h3><h4>${escape(board.title)}</h4><p>${escape(board.purpose)}</p><p class="screen-note">Owner: ${escape(identityName(board.responsibleId))} · ${escape(board.status)}</p><ol>${board.ideaOrder.map(id=>board.ideas.find(entry=>entry.id===id)).filter(Boolean).map(entry=>`<li><h4>${escape(entry.current.title)}</h4><p>${escape(entry.current.body)}</p><p class="screen-note">Exact current idea version: ${entry.current.version}</p>${entry.versions.flatMap(version=>version.decisions.map(decision=>`<p><a href="#study/${encodeURIComponent(state.study.id)}/task/${encodeURIComponent(decision.id)}">${escape(decision.title)}</a> · ${escape(decision.status||'State unavailable')} · cites idea version ${version.item.version}${decision.supersededById?` · <a href="#study/${encodeURIComponent(state.study.id)}/task/${encodeURIComponent(decision.supersededById)}">View replacement</a>`:''}</p>`)).join('')}</li>`).join('')}</ol><p class="screen-note">The downloadable summary also includes retained revisions and decision references.</p></section>`;$('.board-readable').focus();return;}if(action==='move-up'||action==='move-down'){button.disabled=true;try{const order=[...board.ideaOrder];const before=order.indexOf(idea.id);const after=before+(action==='move-up'?-1:1);if(after<0||after>=order.length)return;[order[before],order[after]]=[order[after],order[before]];await updateBoard('/'+encodeURIComponent(board.id)+'/reorder',{ideaIds:order,expectedRevision:board.studyRevision,requestId:crypto.randomUUID()},idea.id,`${idea.current.title} moved to position ${after+1} of ${order.length}.`);}catch(error){notice(error.message,true);}finally{button.disabled=false;}}});

function boardRecordProvenance(item){const source=item.boardDecision;if(source)return `<div class="integration"><strong>Decision from a brainstorming session</strong><a href="#study/${encodeURIComponent(state.study.id)}/idea/board-${encodeURIComponent(source.boardId)}/${encodeURIComponent(source.ideaVersionId)}">View source session</a><p class="screen-note">Exact idea version ${source.ideaVersion} · ${escape(source.ideaVersionId)} · ${escape(identityName(source.sourceAuthor))} · ${escape(source.sourceCreatedAt)}</p></div>`;const idea=item.boardIdea;return idea?`<p class="screen-note"><a href="#study/${encodeURIComponent(state.study.id)}/idea/board-${encodeURIComponent(idea.boardId)}/${encodeURIComponent(item.id)}">Open this idea's named session</a> · Exact idea version ${item.version}</p>`:'';}

function boardHistoryChange(event,board){if(!event.before&&!event.after)return '';const renderSnapshot=(snapshot,label)=>{if(!snapshot)return `<div><h4>${label}</h4><p class="screen-note">Session did not exist.</p></div>`;const order=snapshot.ideaOrder||[];return `<div class="board-history-state"><h4>${label}</h4><dl><dt>Title</dt><dd>${escape(snapshot.title)}</dd><dt>Purpose</dt><dd>${escape(snapshot.purpose)}</dd><dt>Responsible</dt><dd>${escape(identityName(snapshot.responsibleId))}</dd><dt>State</dt><dd>${escape(snapshot.status)}</dd></dl><p class="screen-note">Idea order and exact revisions</p>${order.length?`<ol>${order.map(id=>{const idea=board.ideas.find(candidate=>candidate.id===id);const versionId=snapshot.currentVersions?.[id];const revision=idea?.versions.find(candidate=>candidate.item.id===versionId)?.item;return `<li>${escape(revision?.title||idea?.current?.title||'Removed or unavailable idea')}<span class="check-description">Idea ${escape(id)}${revision?' · Version '+revision.version:''}${versionId?' · Exact revision '+escape(versionId):''}</span></li>`;}).join('')}</ol>`:'<p class="screen-note">No ideas in the ordered list.</p>'}</div>`;};return `<details class="board-history-change"><summary>Before and after this session change</summary><div class="board-history-comparison">${renderSnapshot(event.before,'Before')}${renderSnapshot(event.after,'After')}</div></details>`;}

function recordRoute(studyId,item){const base=`#study/${encodeURIComponent(studyId)}/`;if(item.boardIdea)return base+`idea/board-${encodeURIComponent(item.boardIdea.boardId)}/${encodeURIComponent(item.id)}`;const view=item.kind==='decision'?'task':item.kind==='reply'?'discussion':item.kind==='file'?'document':item.kind==='resource'?'documentation':item.kind;return base+view+(item.id?'/'+encodeURIComponent(item.id):'');}
function focusBoardVersion(board,versionId){const version=board.ideas.flatMap(idea=>idea.versions).find(entry=>entry.item.id===versionId);const target=version?document.getElementById('board-version-'+versionId):null;if(!version||!target){const message=document.createElement('div');message.className='notice error';message.setAttribute('role','alert');message.tabIndex=-1;message.textContent='The requested idea version is unavailable in this session.';$('#board-panel').prepend(message);message.focus();$('#board-live').textContent=message.textContent;return;}for(let parent=target.parentElement;parent;parent=parent.parentElement){if(parent.tagName==='DETAILS')parent.open=true;}target.focus();target.scrollIntoView({block:'center'});$('#board-live').textContent=`Opened ${version.item.title}, exact idea version ${version.item.version}.`;}
document.addEventListener('click',event=>{const link=event.target.closest('a[href]');if(link&&link.getAttribute('href')===location.hash&&(location.hash.startsWith('#study/')||location.hash==='#studies'||location.hash==='#admin')){event.preventDefault();route();}});

function workPlan(){const tasks=items('task');const open=tasks.filter(task=>task.task?.status!=='Done');const completed=tasks.filter(task=>task.task?.status==='Done');const decisions=state.decisionWorkspace||{current:[],history:[]};return `<div class="content-heading"><h2>Tasks & decisions</h2><button class="usa-button" data-action="new" data-kind="task">Add task</button></div><p class="section-description">See what needs to happen next and which decisions currently guide the work. Previous decisions remain in the history.</p><div class="plan-summary"><span><strong>${open.length}</strong> open actions</span><span><strong>${decisions.current.length}</strong> current decisions</span><span><strong>${decisions.history.length}</strong> superseded decisions</span></div><div id="editor"></div><section class="panel"><h3>Open tasks</h3>${open.map(task=>record(task)).join('')||'<p class="muted">No open actions. Capture the next step when the team identifies one.</p>'}${completed.length?`<details class="task-history"><summary>Completed tasks (${completed.length})</summary>${completed.map(task=>record(task)).join('')}</details>`:''}</section><section class="panel decisions-current"><div class="row-head"><h3>Current decisions</h3><button class="text-button" data-action="new" data-kind="decision">+ Record a decision</button></div><p class="screen-note">These records explain the team's working choices. They do not provide external study approval.</p>${decisions.current.map(entry=>record(entry.item)).join('')||'<p class="muted">No decisions recorded yet.</p>'}</section><section class="panel"><details class="decision-history"><summary>Superseded decision history (${decisions.history.length})</summary><p class="screen-note">Earlier rationale, ownership, dates, and evidence remain unchanged.</p>${decisions.history.map(entry=>record(entry.item)).join('')||'<p class="muted">No superseded decisions.</p>'}</details></section>`;}
function decisionInfo(item){return [...(state.decisionWorkspace?.current||[]),...(state.decisionWorkspace?.history||[])].find(entry=>entry.item.id===item.id);}
function decisionMetadata(item){const info=decisionInfo(item);const detail=item.decision;return `<div class="decision-status"><span class="pill ${info?.status==='Superseded'?'paused':''}">${escape(info?.status||'State unavailable')} decision</span>${detail?`<span>Owner: ${escape(identityName(detail.ownerId))}</span><span>Effective: ${escape(detail.effectiveDate)}</span>`:'<span class="screen-note">Legacy decision: owner and effective date were not separately recorded.</span>'}</div>${detail?.alternatives?`<details class="source-provenance"><summary>Alternatives considered</summary><p>${escape(detail.alternatives)}</p></details>`:''}${detail?.reason?`<p class="screen-note"><strong>Change reason:</strong> ${escape(detail.reason)}</p>`:''}${detail?.itemIds?.length?`<div class="evidence-links"><span class="screen-note">Exact supporting records</span><ul>${detail.itemIds.map(id=>`<li>${itemEvidence(id)}</li>`).join('')}</ul></div>`:''}${info?.supersedesId?`<p class="decision-lineage">Supersedes: ${itemEvidence(info.supersedesId)}</p>`:''}${info?.supersededById?`<p class="decision-lineage">Replaced by: ${itemEvidence(info.supersededById)}</p>`:''}`;}
function decisionActions(item){const info=decisionInfo(item);return info?.status!=='Superseded'&&['Reviewer','StudyLead'].includes(state.decisionWorkspace?.studyRole)?`<button class="text-button" data-action="supersede-decision" data-id="${escape(item.id)}">Supersede decision</button>`:'';}
async function showDecisionEditor(source=null,supersede=false){const studyId=state.study.id;try{const members=await api(`/api/studies/${encodeURIComponent(studyId)}/assignees`);if(state.study?.id!==studyId||!$('#editor'))return;const detail=supersede?source.decision:null;const itemIds=supersede?(detail?.itemIds||[source.parentId,source.documentId].filter(Boolean)):source?[source.id]:[];const fileIds=supersede?(detail?.fileIds||source.fileIds||[]):[];$('#editor').innerHTML=`<section class="form-panel"><h3>${supersede?'Supersede a decision':'Record a working decision'}</h3>${supersede?`<div class="decision-before"><p class="label">Immutable previous decision</p><strong>${escape(source.title)}</strong><p>${escape(source.body)}</p><p class="screen-note">${escape(source.author)} · ${escape(source.createdAt)} · exact record ${escape(source.id)}</p></div>`:''}<form id="typed-decision-form" data-prior="${supersede?escape(source.id):''}" data-revision="${state.study.revision}" data-request="${crypto.randomUUID()}"><label class="usa-label" for="decision-title">Decision title</label><input class="usa-input" id="decision-title" name="title" required maxlength="180" value="${supersede?escape(source.title):''}"><label class="usa-label" for="decision-rationale">Decision and rationale</label><textarea class="usa-textarea" id="decision-rationale" name="rationale" required maxlength="20000">${supersede?escape(source.body):''}</textarea><label class="usa-label" for="decision-alternatives">Alternatives considered</label><textarea class="usa-textarea" id="decision-alternatives" name="alternatives" maxlength="4000">${escape(detail?.alternatives||'')}</textarea><div class="decision-fields"><div><label class="usa-label" for="decision-owner">Decision owner</label><select class="usa-select" id="decision-owner" name="ownerId" required>${detail?.ownerId&&!members.some(member=>member.id===detail.ownerId)?'<option value="" selected disabled>Previous owner unavailable — choose a participant</option>':''}${members.map(member=>`<option value="${escape(member.id)}" ${member.id===(detail?.ownerId||state.session.user.id)?'selected':''}>${escape(member.name)}</option>`).join('')}</select></div><div><label class="usa-label" for="decision-effective">Effective date</label><input class="usa-input" type="date" id="decision-effective" name="effectiveDate" required min="1900-01-01" max="2100-12-31" value="${escape(detail?.effectiveDate||new Date().toISOString().slice(0,10))}"></div></div><label class="usa-label" for="decision-reason">${supersede?'Reason for superseding':'Record context (optional)'}</label><textarea class="usa-textarea" id="decision-reason" name="reason" maxlength="1000" ${supersede?'required':''}></textarea><fieldset class="evidence-picker"><legend>Exact supporting records (optional)</legend><p class="form-hint">To turn a managed brainstorming idea into a decision, use Record decision in its named session so the exact version is preserved.</p>${items().filter(item=>!item.boardIdea&&(item.id!==source?.id||!supersede)).map(item=>`<label><input type="checkbox" name="itemIds" value="${escape(item.id)}" ${itemIds.includes(item.id)?'checked':''}>${escape(item.title)} · ${escape(item.kind)} version ${item.version}</label>`).join('')}</fieldset>${fileEvidencePicker('fileIds',fileIds)}<p class="form-hint">${supersede?'Creates a new current decision and retains the previous decision unchanged.':'Records a working choice with its exact evidence.'} This is not external study approval.</p><div class="form-row"><button class="usa-button" type="submit">${supersede?'Save superseding decision':'Save decision'}</button><button class="text-button" type="button" data-action="cancel">Cancel</button></div><p id="form-error" class="form-hint" role="alert"></p></form></section>`;$('#decision-title').focus();}catch(error){notice(error.message,true);}}
document.addEventListener('submit',async event=>{const form=event.target;if(form.id!=='typed-decision-form')return;event.preventDefault();const button=$('button[type=submit]',form);button.disabled=true;try{const fields=new FormData(form);await api(`/api/studies/${encodeURIComponent(state.study.id)}/decisions${form.dataset.prior?'/'+encodeURIComponent(form.dataset.prior)+'/supersede':''}`,{...Object.fromEntries(fields),itemIds:fields.getAll('itemIds'),fileIds:fields.getAll('fileIds'),expectedRevision:Number(form.dataset.revision),requestId:form.dataset.request});await route();$('#main').focus();notice('Saved. The shared record has been updated.');}catch(error){notice(error.message,true);$('#form-error').textContent='Your decision draft is retained. Review fresh study context before retrying a stale change.';}finally{button.disabled=false;}});

async function loadDocumentationResources(){const studyId=state.study.id;const ticket=state.route;try{const [templates,resources]=await Promise.all([api(`/api/studies/${encodeURIComponent(studyId)}/templates`),api(`/api/studies/${encodeURIComponent(studyId)}/resources`)]);if(state.route!==ticket||!$('#documentation-tools'))return;state.templates=templates;state.resources=resources;$('#documentation-tools').innerHTML=`<section class="panel"><h3>Start from a useful template</h3><p class="screen-note">Each template creates an editable Draft document in its own stable family. It does not change existing study records.</p>${state.documentWorkspace?.studyRole==='StudyLead'?'<button class="text-button" data-template-new>Create study template</button>':''}<div class="template-grid">${templates.map(template=>`<article class="template-card"><p class="eyebrow">Draft starting point · Definition v${escape(template.version||1)}</p><h4>${escape(template.title)}</h4><p>${escape(template.description)}</p><button class="text-button" data-template-id="${escape(template.id)}">Use ${escape(template.title)} template</button><button class="text-button" data-template-history="${escape(template.id)}">Template history <span class="usa-sr-only">${escape(template.title)}</span></button>${state.documentWorkspace?.studyRole==='StudyLead'?`<button class="text-button" data-template-edit="${escape(template.id)}">Revise template <span class="usa-sr-only">${escape(template.title)}</span></button>`:''}</article>`).join('')}</div><div id="template-history"></div></section><section class="panel"><div class="row-head"><h3>Study resource pointers</h3><button class="text-button" data-resource-action="new">Add resource pointer</button></div><p class="screen-note">Maintained references to existing resources. The hub does not provision access or fetch these destinations.</p>${resourceFamilies(resources)||'<p class="muted">No pointers recorded. Add a URL or local description with its source, owner, and verification date.</p>'}</section><h3>Living study notes</h3>`;const requested=location.hash.slice(1).split('/')[3];if(requested){const target=document.getElementById('record-'+decodeURIComponent(requested));if(target){for(let parent=target.parentElement;parent;parent=parent.parentElement)if(parent.tagName==='DETAILS')parent.open=true;target.tabIndex=-1;target.focus();target.scrollIntoView({block:'center'});}}}catch(error){if(state.route===ticket&&state.study?.id===studyId&&$('#documentation-tools'))$('#documentation-tools').innerHTML=`<div class="notice error">${escape(error.message)}</div>`;}}
function resourcePointer(item){const resource=item.resource;const age=resource?.lastVerified?Math.floor((Date.now()-new Date(resource.lastVerified+'T00:00:00Z'))/86400000):null;const stale=age!==null&&age>90;return `<article class="record resource-pointer" id="record-${escape(item.id)}"><div class="row-head"><h4>${escape(item.title)}</h4><span class="pill ${stale?'paused':''}">${stale?'Review freshness':'Recorded pointer'}</span></div>${item.body?`<p>${escape(item.body)}</p>`:''}${resource?.url?`<p><a href="${escape(resource.url)}" rel="noreferrer noopener" target="_blank">Open resource <span class="usa-sr-only">${escape(item.title)} (opens a new tab)</span><span aria-hidden="true"> ↗</span></a></p>`:'<p class="screen-note">Local description; no destination link.</p>'}<dl class="resource-facts"><div><dt>Responsible participant</dt><dd>${escape(identityName(resource?.ownerId))}</dd></div><div><dt>Source</dt><dd>${escape(resource?.source)}</dd></div><div><dt>Last verified by the contributor</dt><dd>${escape(resource?.lastVerified||'Not recorded')}${age!==null?' · '+age+' days ago':''}</dd></div></dl><p class="screen-note">${stale?'More than 90 days since the entered verification date; confirm this pointer with its owner.':'Verification is recorded by the contributor; the application has not checked the destination.'}</p></article>`;}
async function showResourceEditor(source=null,operation='replace'){const studyId=state.study.id;const ticket=state.route;try{const members=await api(`/api/studies/${encodeURIComponent(studyId)}/assignees`);if(state.route!==ticket||state.study?.id!==studyId||!$('#editor'))return;$('#editor').innerHTML=`<section class="form-panel"><h3>${source?(operation==='reverify'?'Record a new verification':'Replace resource pointer'):'Add a resource pointer'}</h3><form id="resource-form" data-source="${escape(source?.id||'')}" data-operation="${operation}" data-study="${escape(studyId)}" data-revision="${state.resources?.revision||state.study.revision}" data-request="${crypto.randomUUID()}"><label class="usa-label" for="resource-title">Resource title</label><input class="usa-input" name="title" id="resource-title" required maxlength="180"><label class="usa-label" for="resource-url">Resource URL (optional)</label><input class="usa-input" name="url" id="resource-url" type="url" maxlength="2000" placeholder="https://example.org/reference"><label class="usa-label" for="resource-body">Local description or access guidance</label><textarea class="usa-textarea" name="body" id="resource-body" maxlength="20000"></textarea><p class="form-hint">Provide a URL or a local description. Use synthetic references only. Saving does not open the destination or grant access.</p><label class="usa-label" for="resource-owner">Pointer owner</label><select class="usa-select" name="ownerId" id="resource-owner" required>${members.map(member=>`<option value="${escape(member.id)}" ${member.id===state.session.user.id?'selected':''}>${escape(member.name)}</option>`).join('')}</select><label class="usa-label" for="resource-source">Source of this information</label><input class="usa-input" name="source" id="resource-source" required maxlength="300"><label class="usa-label" for="resource-verified">Last verified date</label><input class="usa-input" type="date" name="lastVerified" id="resource-verified" required min="1900-01-01" max="${new Date().toISOString().slice(0,10)}">${source?'<label class="usa-label" for="resource-reason">Reason for this revision</label><textarea class="usa-textarea" id="resource-reason" name="reason" required maxlength="1000"></textarea><p class="form-hint">Creates a retained immutable revision; earlier values remain available.</p>':''}<div class="form-row"><button class="usa-button" type="submit">Save resource pointer</button><button class="text-button" type="button" data-action="cancel">Cancel</button></div><p id="form-error" class="form-hint" role="alert"></p></form></section>`;if(source){const form=$('#resource-form');for(const [key,value] of Object.entries({title:source.title,body:source.body,url:source.resource?.url||'',ownerId:source.resource?.ownerId,source:source.resource?.source,lastVerified:source.resource?.lastVerified})){if(form.elements[key])form.elements[key].value=value||'';}if(operation==='reverify')for(const key of ['title','body','url','ownerId','source'])form.elements[key].disabled=true;}$('#resource-title').disabled?$('#resource-verified').focus():$('#resource-title').focus();}catch(error){if(ticket===state.route)notice(error.message,true);}}
document.addEventListener('click',event=>{const templateButton=event.target.closest('[data-template-id]');if(templateButton){const template=state.templates?.find(entry=>entry.id===templateButton.dataset.templateId);if(template)showDocumentEditor({title:template.title,body:template.body},false,template);}if(event.target.closest('[data-resource-action="new"]'))showResourceEditor();});
document.addEventListener('submit',async event=>{const form=event.target;if(form.id!=='resource-form')return;event.preventDefault();const button=$('button[type=submit]',form);button.disabled=true;const ticket=state.route;try{const fields=Object.fromEntries(new FormData(form));await api(`/api/studies/${encodeURIComponent(form.dataset.study)}/resources${form.dataset.source?'/'+encodeURIComponent(form.dataset.source)+'/'+form.dataset.operation:''}`,{...fields,url:fields.url||null,expectedRevision:Number(form.dataset.revision),requestId:form.dataset.request});if(ticket!==state.route)return;await route();$('#main').focus();notice('Resource pointer saved. No destination was contacted.');}catch(error){if(ticket!==state.route)return;notice(error.message,true);$('#form-error').textContent='Your pointer draft is retained. Check the fields or refresh stale study context before retrying.';}finally{button.disabled=false;}});

function capturedDecisionMetadata(item,captured,resolveEvidence){const details=item.decision;return `<div class="captured-decision"><span class="pill ${captured?.status==='Superseded'?'paused':''}">Decision state at capture: ${escape(captured?.status||'State not captured')}</span>${details?`<p class="screen-note">Captured owner: ${escape(details.ownerId)} · Effective: ${escape(details.effectiveDate)}</p>${details.alternatives?`<details class="source-provenance"><summary>Captured alternatives considered</summary><p>${escape(details.alternatives)}</p></details>`:''}${details.reason?`<p class="screen-note">Captured change reason: ${escape(details.reason)}</p>`:''}`:'<p class="screen-note">Separate owner and effective-date fields were not recorded for this decision.</p>'}${captured?.supersedesId?`<p class="screen-note">Captured predecessor: ${resolveEvidence(captured.supersedesId)}</p>`:''}${captured?.supersededById?`<p class="screen-note">Captured replacement: ${resolveEvidence(captured.supersededById)}</p>`:''}</div>`;}

function capturedResourceMetadata(item){const pointer=item.resource;if(!pointer)return '<p class="screen-note">Resource metadata was not captured.</p>';return `<dl class="resource-facts"><div><dt>Captured pointer owner</dt><dd>${escape(pointer.ownerId)}</dd></div><div><dt>Captured source</dt><dd>${escape(pointer.source)}</dd></div><div><dt>Entered verification date at capture</dt><dd>${escape(pointer.lastVerified)}</dd></div></dl>${pointer.url?`<p><a href="${escape(pointer.url)}" target="_blank" rel="noreferrer noopener">Open captured resource URL <span class="usa-sr-only">(opens a new tab)</span></a></p>`:'<p class="screen-note">Captured local description; no destination URL.</p>'}<p class="screen-note">This is the pointer metadata as captured. The application has not contacted or verified the destination.</p>`;}

function renderRecordBody(item){const body=String(item.body||'');if(item.kind!=='documentation'||!/^1\.\s/.test(body)||!body.includes('\n'))return `<p>${escape(body)}</p>`;const paragraphs=body.split(/\n\s*\n/);let output='',listOpen=false;for(const paragraph of paragraphs){const step=paragraph.match(/^(\d{1,3})\.\s+([\s\S]+)$/);if(step){if(!listOpen){output+='<ol class="guidance-steps">';listOpen=true;}output+=`<li value="${Number(step[1])}">${escape(step[2])}</li>`;}else{if(listOpen){output+='</ol>';listOpen=false;}output+=`<p>${escape(paragraph)}</p>`;}}return output+(listOpen?'</ol>':'');}
async function loadSearchPage(query,page=1,filters=state.search?.filters||{}){notice('');const ticket=++state.route;const user=state.session?.user.id;state.search={...(state.search||{}),query,filters};state.study=null;$('#main').setAttribute('aria-busy','true');$('#main').innerHTML='<p role="status">Searching your accessible study records…</p>';try{const response=await api(`/api/search?q=${encodeURIComponent(query)}&page=${page}&pageSize=25${filters.studyId?'&studyId='+encodeURIComponent(filters.studyId):''}${filters.kind?'&kind='+encodeURIComponent(filters.kind):''}`);if(ticket!==state.route||user!==state.session?.user.id)return;const result=Array.isArray(response)?{items:response,total:response.length,page:1,pageSize:response.length||25,hasMore:false}:response;if(result.page>Math.max(1,Math.ceil(result.total/result.pageSize)))return loadSearchPage(query,Math.max(1,Math.ceil(result.total/result.pageSize)),filters);state.search={query,filters,...result};const start=result.items.length?(result.page-1)*result.pageSize+1:0;const end=start?start+result.items.length-1:0;$('#main').innerHTML=`<div class="page-heading"><div><p class="eyebrow">Permission-aware search</p><h1>Search results</h1><p class="muted">${result.total} results for “${escape(query)}” within your accessible studies.</p></div></div>${searchFilters(result.facets,filters)}<p class="screen-note" role="status">Showing ${start}–${end} of ${result.total} results</p><p class="screen-note">Search covers record titles and text, uploaded filenames, task assignees/status/due dates, decision owners/reasons/alternatives, and resource owners/sources/URLs. It does not extract text from uploaded files.</p><p class="screen-note">Results and totals may change as study content or access changes.</p><section class="panel">${result.items.map(resultItem=>{const item=resultItem.item||resultItem;return `<article class="record"><p class="record-meta">${escape(resultItem.studyTitle||resultItem.studyId)} · ${escape(item.kind)}</p><h2><a href="${recordRoute(resultItem.studyId||item.studyId,item)}">${escape(item.title)}</a></h2><p>${escape(item.body?.slice(0,250))}</p>${resultItem.context?`<p class="search-context">${escape(resultItem.context)}</p>`:''}</article>`;}).join('')||'<div class="empty"><h2>No matching records</h2><p>Try a different phrase or broaden the study and record type filters. Inaccessible and deleted content is excluded.</p></div>'}</section><nav class="search-pagination" aria-label="Search result pages"><button class="usa-button usa-button--outline" type="button" data-search-page="${result.page-1}" ${result.page<=1?'disabled':''}>Previous results</button><span>Page ${result.page}${result.total?' of '+Math.ceil(result.total/result.pageSize):''}</span><button class="usa-button usa-button--outline" type="button" data-search-page="${result.page+1}" ${result.hasMore?'':'disabled'}>Next results</button></nav>`;$('#main').focus();}catch(error){if(ticket===state.route&&user===state.session?.user.id)$('#main').innerHTML=`<section class="panel empty"><h1>Search unavailable</h1><p>${escape(error.message)}</p>${searchFilters(state.search?.facets,filters)}<p>Your query is still in the search box. Try again or <a href="#studies">return to My studies</a>.</p></section>`;}finally{if(ticket===state.route)$('#main').removeAttribute('aria-busy');}}
document.addEventListener('click',event=>{const button=event.target.closest('[data-search-page]');if(button&&!button.disabled&&state.search)loadSearchPage(state.search.query,Number(button.dataset.searchPage));});

function renderImportReview(){const review=state.importReview;if(!review||!$('#import-review-workspace'))return;$('#import-review-workspace').innerHTML=`<section class="exception-review"><div class="row-head"><h3>Import exception review</h3><span class="count-badge">${review.cases.filter(entry=>entry.state!=='Resolved').length} open exceptions</span></div><p class="screen-note">Assign responsibility, record review, and track corrections. Resolving an exception closes operator tracking only; it does not release quarantined content or grant acceptance.</p>${review.cases.map((entry,index)=>`<article class="record"><div class="row-head"><h4>${escape(entry.sourceId)}</h4><span class="pill">${escape(entry.state)}</span></div><p>${escape(entry.status)} · ${escape(entry.disposition||'No disposition')} · Owner: ${escape(entry.ownerId?identityName(entry.ownerId):'Unassigned')}</p><p>${(entry.reasons||[]).map(escape).join('; ')}</p><p class="screen-note">Batch ${escape(entry.reportId)}</p><button class="text-button" data-import-case="${index}">Review exception <span class="usa-sr-only">${escape(entry.sourceId)}</span></button><details><summary>Exception history (${(entry.history||[]).length})</summary>${(entry.history||[]).map(event=>`<div class="history-entry"><strong>${escape(event.action||event.state)}</strong> · ${escape(identityName(event.actor))} · ${date(event.at)}<p>${escape(event.note)}</p><p class="screen-note">${escape(event.disposition||'')} ${event.ownerId?' · Owner '+escape(identityName(event.ownerId)):''}</p></div>`).join('')||'<p>No review events recorded.</p>'}</details></article>`).join('')||'<p class="muted">No quarantined or stale records need operator review.</p>'}<div id="import-case-editor"></div><h3>Immutable batch receipts</h3><p class="screen-note">A receipt records this batch’s outcomes and operator review at capture time. It is not a full source inventory, migration certification, or acceptance.</p>${(review.receipts||[]).map(receipt=>`<article class="record"><h4>Receipt for batch ${escape(receipt.reportId)}</h4><p class="record-meta">${date(receipt.at)} · ${escape(identityName(receipt.actor))} · Revision ${receipt.studyRevision}</p><button class="text-button" data-receipt-view="${escape(receipt.id)}">View captured receipt</button> <a href="/api/studies/${encodeURIComponent(state.study.id)}/imports/receipts/${encodeURIComponent(receipt.id)}/export">Download receipt JSON</a></article>`).join('')||'<p class="muted">Capture a receipt from a saved import report when ready to retain its current review context.</p>'}<div id="import-receipt-detail"></div></section>`;}
function showImportCase(index){const entry=state.importReview?.cases[index];if(!entry)return;const review=state.importReview;$('#import-case-editor').innerHTML=`<section class="form-panel"><h3>Review ${escape(entry.sourceId)}</h3><form id="import-case-form" data-case="${index}" data-study="${escape(state.study.id)}" data-revision="${review.studyRevision}" data-request="${crypto.randomUUID()}"><label class="usa-label" for="exception-owner">Exception owner</label><select class="usa-select" name="ownerId" id="exception-owner" required><option value="">Choose a study member</option>${review.members.map(member=>`<option value="${escape(member.id)}" ${member.id===entry.ownerId?'selected':''}>${escape(member.name)}</option>`).join('')}</select><label class="usa-label" for="exception-action">Review action</label><select class="usa-select" name="action" id="exception-action">${(entry.state==='Resolved'?['Reopen']:entry.ownerId?['Assign','Review','Resolve']:['Assign']).map(action=>`<option>${action}</option>`).join('')}</select><label class="usa-label" for="exception-disposition">Disposition</label><select class="usa-select" name="disposition" id="exception-disposition"><option value="NeedsCorrection">Needs correction</option><option value="Excluded">Excluded from this batch</option><option value="CorrectedInLaterImport">Corrected in a later import</option></select><label class="usa-label" for="exception-successor">Later correction batch (if corrected)</label><select class="usa-select" name="successorReportId" id="exception-successor"><option value="">No correction batch</option>${review.reports.filter(report=>report.id!==entry.reportId).map(report=>`<option value="${escape(report.id)}">${date(report.at)} · ${escape(report.id)}</option>`).join('')}</select><label class="usa-label" for="exception-note">Review note</label><textarea class="usa-textarea" id="exception-note" name="note" maxlength="1000" required></textarea><p class="form-hint">Every action requires an owner. Assign ownership before review; reassign explicitly before changing the owner. Resolving requires exclusion or an actual later correction for this source record.</p><button class="usa-button" type="submit">Save exception review</button><p class="form-hint" role="alert" id="exception-error"></p></form></section>`;syncImportReviewForm();$('#exception-owner').focus();}
document.addEventListener('submit',async event=>{const form=event.target;if(form.id!=='import-case-form')return;event.preventDefault();const button=$('button[type=submit]',form);button.disabled=true;const ticket=state.route;const entry=state.importReview.cases[Number(form.dataset.case)];try{const fields=Object.fromEntries(new FormData(form));await api(`/api/studies/${encodeURIComponent(form.dataset.study)}/imports/${encodeURIComponent(entry.reportId)}/review`,{...fields,sourceId:entry.sourceId,ownerId:fields.ownerId||null,successorReportId:fields.successorReportId||null,expectedRevision:Number(form.dataset.revision),requestId:form.dataset.request});if(ticket!==state.route)return;await loadImportReports();notice('Exception review recorded. Quarantined content remains unchanged.');$('#import-review-workspace')?.focus();$('#import-review-workspace')?.scrollIntoView({block:'start'});}catch(error){if(ticket===state.route&&$('#exception-error'))$('#exception-error').textContent=error.message+' Your review draft is retained.';}finally{button.disabled=false;}});
document.addEventListener('click',async event=>{const caseButton=event.target.closest('[data-import-case]');if(caseButton)showImportCase(Number(caseButton.dataset.importCase));const capture=event.target.closest('[data-import-receipt]');const view=event.target.closest('[data-receipt-view]');if(!capture&&!view)return;const button=capture||view;button.disabled=true;const ticket=state.route;const studyId=state.study.id;try{const receipt=capture?await api(`/api/studies/${encodeURIComponent(studyId)}/imports/${encodeURIComponent(capture.dataset.importReceipt)}/receipts`,{expectedRevision:state.importReview.studyRevision,requestId:capture.dataset.request||(capture.dataset.request=crypto.randomUUID())}):await api(`/api/studies/${encodeURIComponent(studyId)}/imports/receipts/${encodeURIComponent(view.dataset.receiptView)}`);if(ticket!==state.route)return;if(capture)await loadImportReports();if(ticket!==state.route||!$('#import-receipt-detail'))return;$('#import-receipt-detail').innerHTML=`<section class="form-panel" tabindex="-1"><h3>Captured batch receipt</h3><p class="screen-note">Immutable batch outcome and review snapshot. Later corrections do not rewrite this receipt.</p><dl><dt>Batch</dt><dd>${escape(receipt.reportId)}</dd><dt>Captured</dt><dd>${date(receipt.at)} · ${escape(identityName(receipt.actor))}</dd><dt>SHA-256</dt><dd><code>${escape(receipt.sha256)}</code></dd></dl>${receipt.report?renderImportReport(receipt.report):''}<h4>Review at capture time</h4>${(receipt.cases||[]).map(entry=>`<article class="record"><h5>${escape(entry.sourceId)}</h5><p>${escape(entry.state)} · ${escape(entry.disposition||'No disposition')} · Owner: ${escape(entry.ownerId?identityName(entry.ownerId):'Unassigned')}</p><p>${(entry.reasons||[]).map(escape).join('; ')}</p>${(entry.history||[]).map(event=>`<p class="screen-note">${escape(event.action)} · ${date(event.at)} · ${escape(event.note)}</p>`).join('')}</article>`).join('')||'<p>No exception review captured.</p>'}<details><summary>Captured outcomes and review details</summary><pre class="receipt-json">${escape(JSON.stringify(receipt,null,2))}</pre></details></section>`;$('#import-receipt-detail section').focus();}catch(error){if(ticket===state.route)notice(error.message,true);}finally{button.disabled=false;}});

function searchFilters(facets,filters){const labels={document:'Document versions',documentation:'Living notes',discussion:'Discussions',reply:'Replies',decision:'Decisions',task:'Tasks',idea:'Ideas',resource:'Resource pointers',file:'Uploaded files'};const studies=[...(facets?.studies||[])];if(filters.studyId&&!studies.some(study=>study.id===filters.studyId))studies.push({id:filters.studyId,title:'Previously selected study'});return `<form id="search-filter-form" class="search-filters"><div><label class="usa-label" for="search-study">Study</label><select class="usa-select" id="search-study" name="studyId"><option value="">All accessible studies</option>${studies.map(study=>`<option value="${escape(study.id)}" ${study.id===filters.studyId?'selected':''}>${escape(study.title)}</option>`).join('')}</select></div><div><label class="usa-label" for="search-kind">Record type</label><select class="usa-select" id="search-kind" name="kind"><option value="">All record types</option>${Object.entries(labels).map(([kind,label])=>`<option value="${kind}" ${kind===filters.kind?'selected':''}>${label}</option>`).join('')}</select></div><button class="usa-button usa-button--outline" type="submit">Apply search filters</button></form>`;}
document.addEventListener('submit',event=>{if(event.target.id!=='search-filter-form')return;event.preventDefault();loadSearchPage($('#search').value.trim(),1,Object.fromEntries(new FormData(event.target)));});

function resourceFamilies(resources){const all=resources.resources||[];const current=resources.current||all;const history=resources.history||[];return current.map(item=>{const family=item.resource?.versionDetails?.familyId||item.id;const retained=history.filter(previous=>(previous.resource?.versionDetails?.familyId||previous.id)===family);return `<section class="resource-family">${resourcePointer(item)}<p class="screen-note">Current pointer · Version ${item.version||1}${item.resource?.versionDetails?.reason?' · '+escape(item.resource.versionDetails.reason):''}</p><div class="record-actions"><button class="text-button" data-resource-replace="${escape(item.id)}">Replace pointer</button><button class="text-button" data-resource-reverify="${escape(item.id)}">Record verification</button></div>${retained.length?`<details class="version-disclosure"><summary>Retained pointer history (${retained.length}) <span class="usa-sr-only">for ${escape(item.title)}</span></summary>${retained.map(previous=>`<div class="retained-resource"><p class="eyebrow">Retained version ${previous.version||1} · ${escape(previous.resource?.versionDetails?.operation||'Created')}</p>${resourcePointer(previous)}<p class="screen-note">${escape(previous.resource?.versionDetails?.reason||'')}</p></div>`).join('')}</details>`:''}</section>`;}).join('');}
function showTemplateEditor(template=null){$('#editor').innerHTML=`<section class="form-panel"><h3>${template?'Revise study template':'Create study template'}</h3><p class="screen-note">Template definitions are immutable versions. Existing documents retain the exact template definition they used.</p><form id="template-form" data-template="${escape(template?.id||'')}" data-study="${escape(state.study.id)}" data-revision="${state.study.revision}" data-request="${crypto.randomUUID()}"><label class="usa-label" for="template-title">Template title</label><input class="usa-input" id="template-title" name="title" required maxlength="180" value="${escape(template?.title||'')}"><label class="usa-label" for="template-description">Template description</label><textarea class="usa-textarea" id="template-description" name="description" required maxlength="1000">${escape(template?.description||'')}</textarea><label class="usa-label" for="template-body">Template starting content</label><textarea class="usa-textarea" id="template-body" name="body" required maxlength="20000">${escape(template?.body||'')}</textarea><label class="usa-label" for="template-reason">Template change reason</label><textarea class="usa-textarea" id="template-reason" name="reason" required maxlength="1000"></textarea><button class="usa-button" type="submit">Save template version</button><p id="template-error" role="alert" class="form-hint"></p></form></section>`;$('#template-title').focus();}
document.addEventListener('submit',async event=>{const form=event.target;if(form.id!=='template-form')return;event.preventDefault();const button=$('button[type=submit]',form);button.disabled=true;const ticket=state.route;try{await api(`/api/studies/${encodeURIComponent(form.dataset.study)}/templates${form.dataset.template?'/'+encodeURIComponent(form.dataset.template)+'/versions':''}`,{...Object.fromEntries(new FormData(form)),expectedRevision:Number(form.dataset.revision),requestId:form.dataset.request});if(ticket!==state.route)return;await route();notice('Template version saved. Existing Draft provenance is unchanged.');}catch(error){if(ticket===state.route&&$('#template-error'))$('#template-error').textContent=error.message+' Your draft is retained.';}finally{button.disabled=false;}});
document.addEventListener('click',async event=>{const replace=event.target.closest('[data-resource-replace]');const reverify=event.target.closest('[data-resource-reverify]');if(replace||reverify){const id=replace?.dataset.resourceReplace||reverify.dataset.resourceReverify;const item=state.resources.resources.find(item=>item.id===id);if(item)showResourceEditor(item,reverify?'reverify':'replace');}if(event.target.closest('[data-template-new]'))showTemplateEditor();const edit=event.target.closest('[data-template-edit]');if(edit)showTemplateEditor(state.templates.find(template=>template.id===edit.dataset.templateEdit));const use=event.target.closest('[data-template-version-use]');if(use){const template=state.templateHistory?.find(template=>template.versionId===use.dataset.templateVersionUse);if(template)showDocumentEditor({title:template.title,body:template.body},false,template);}const history=event.target.closest('[data-template-history]');if(!history)return;const ticket=state.route;try{const versions=await api(`/api/studies/${encodeURIComponent(state.study.id)}/templates/${encodeURIComponent(history.dataset.templateHistory)}/versions`);if(ticket!==state.route||!$('#template-history'))return;state.templateHistory=versions;$('#template-history').innerHTML=`<section class="template-history" tabindex="-1"><h4>Template definition history</h4>${versions.slice().reverse().map(template=>`<details class="version-disclosure"><summary>${escape(template.title)} · Definition version ${template.version}</summary><p class="record-meta">${escape(identityName(template.actor))} · ${date(template.createdAt)}</p><p>${escape(template.reason)}</p><pre class="template-preview">${escape(template.body)}</pre><button class="text-button" data-template-version-use="${escape(template.versionId)}">Use definition version ${template.version}</button></details>`).join('')}</section>`;$('#template-history section').focus();}catch(error){if(ticket===state.route)notice(error.message,true);}});

function syncImportReviewForm(){const form=$('#import-case-form');if(!form)return;const action=form.elements.action.value;const disposition=form.elements.disposition;const previous=disposition.value;const values=action==='Resolve'?[['Excluded','Excluded from this batch'],['CorrectedInLaterImport','Corrected in a later import']]:[['NeedsCorrection','Needs correction']];disposition.innerHTML=values.map(([value,label])=>`<option value="${value}" ${value===previous?'selected':''}>${label}</option>`).join('');const corrected=disposition.value==='CorrectedInLaterImport';form.elements.successorReportId.disabled=!corrected;form.elements.successorReportId.required=corrected;if(!corrected)form.elements.successorReportId.value='';}
document.addEventListener('change',event=>{if(event.target.id==='exception-action'||event.target.id==='exception-disposition')syncImportReviewForm();});
